/* ===== 07-utilities/05-ids.js ===== */
  // --- IDs ---
  function generateId(prefix) { return prefix + '_' + Math.random().toString(36).substr(2, 8); }

/* ===== 07-utilities/06-getters.js ===== */
  // --- Collection getters ---
  function getHubClusters(hubId) { return (S.data.clusters || []).filter(function(c) { return c.hub_id === hubId; }); }
  function getHubContent(hubId) { return (S.data.content || []).filter(function(c) { return c.hub_id === hubId; }); }
  function getClusterContent(clusterId) { return (S.data.content || []).filter(function(c) { return c.cluster_id === clusterId; }); }
  function getContentType(typeId) { return S.contentTypeMap[typeId] || null; }
  function getTemplate(templateId) { return S.templateMap[templateId] || null; }
  function resolveTag(id) { return S.tagMap[id] || null; }
  function getRecentActivity(n) { return (S.activity || []).slice(-(n || 15)).reverse(); }
  function getAllTags() { return (S.data.tags || []).slice().sort(function(a, b) { return (a.name || '').localeCompare(b.name || ''); }); }
  function getImages(filters) {
    var imgs = S.images.slice();
    if (!filters) return imgs;
    if (filters.star) imgs = imgs.filter(function(img) { return img.star; });
    if (filters.category) imgs = imgs.filter(function(img) { return img.category === filters.category; });
    if (filters.search) {
      var q = filters.search.toLowerCase();
      imgs = imgs.filter(function(img) { return (img.filename || '').toLowerCase().indexOf(q) > -1 || (img.description || '').toLowerCase().indexOf(q) > -1; });
    }
    return imgs;
  }

/* ===== 07-utilities/07-keyword-groups.js ===== */
  // --- Keyword Group Helpers ---
  function getContentKeywordGroups(contentId) {
    return (S.data.keyword_groups || []).filter(function(g) { return g.content_id === contentId; });
  }
  function getHubKeywordGroups(hubId) {
    return (S.data.keyword_groups || []).filter(function(g) { return g.hub_id === hubId; });
  }
  function getUnlinkedKeywordGroups() {
    return (S.data.keyword_groups || []).filter(function(g) { return !g.content_id; });
  }

/* ===== 07-utilities/08-misc.js ===== */
  // --- Misc ---
  function debounce(fn, delay) { var t; return function() { var c = this, a = arguments; clearTimeout(t); t = setTimeout(function() { fn.apply(c, a); }, delay); }; }
  function deepClone(obj) { return JSON.parse(JSON.stringify(obj)); }
  function isEmpty(obj) { return !obj || (typeof obj === 'object' && Object.keys(obj).length === 0); }

/* ===== 07-utilities/09-wcp-select.js ===== */
  // ============================================================
  // SECTION 7.9: WcpSelect — modern searchable dropdown
  // ============================================================
  //
  // Renders a rich select (icon + color dot + label + description) on top of
  // a hidden native <select.wcp-step-field>. The hidden select carries the
  // `data-path` contract, so the existing field-save handler in part2a's
  // `setupPart2aEventHandlers()` (see `.wcp-step-field` change handler in
  // src/part2a/15-events.js) keeps working unchanged — picking an option
  // syncs the hidden select's value and dispatches a native change event.
  //
  // Usage (from any renderer):
  //   html += _wcpSelect.render({
  //     name: 'content_type_id',
  //     dataPath: 'content_type_id',
