    if (s === '1' || s === 'p1' || s === 'high' || s === 'pillar') return 1;
    if (s === '2' || s === 'p2' || s === 'medium' || s === 'cluster') return 2;
    if (s === '3' || s === 'p3' || s === 'low' || s === 'standard') return 3;
