    html += '<button class="wcp-btn-ai wcp-btn-sm" data-action="ai-gap-analysis" data-hub="' + esc(hub.id) + '" title="AI proposes new clusters to fill coverage gaps">' + icon('sparkles') + ' Gap Analysis</button>';
