    $(document).off('dragend' + ns + '-de').on('dragend' + ns + '-de', '.wcp-outline-row', function() {
      dragIdx = null;
      $('.wcp-outline-row').removeClass('wcp-outline-row-dragging wcp-outline-row-drop-target');
    });

