  function aiSuggestType(contentId) {
    var c = S.contentMap[contentId]; if (!c) return;
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var types = (S.data.content_types || []).map(function(t) { return t.name + ' — ' + t.description; }).join('\n');
    var bi = c.basic_info || {};
    var prompt = 'Suggest the best content type for this piece.\n\n';
    prompt += 'Title: ' + esc(c.title || '') + '\n';
    if (bi.audience) prompt += 'Audience: ' + bi.audience + '\n';
    if (bi.goal)     prompt += 'Goal: ' + bi.goal + '\n';
    prompt += '\nAvailable types:\n' + types;
    prompt += brandSnippet('research');
    prompt += '\n\nRespond ONLY as JSON: {"suggested_type":"exact type name from list","reasoning":"1 sentence"}';
    _wcpAIPreflight.run({
      actionId: 'ai-suggest-type',
      title: 'Suggest content type',
      description: 'AI will pick the best matching content type for "' + (c.title || 'this piece') + '".',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        if (parsed.suggested_type) {
          var matched = (S.data.content_types || []).find(function(t) { return t.name.toLowerCase() === parsed.suggested_type.toLowerCase(); });
          if (matched) c.content_type_id = matched.id;
        }
        c.updated = new Date().toISOString();
        logActivity('ai_action', c.id, c.title, 'AI suggested type: ' + (parsed.suggested_type || ''));
        snapshot('AI suggest type'); buildMaps(); syncToTextarea(); render();
        toast('Type suggested: ' + (parsed.suggested_type || 'see results') + (parsed.reasoning ? ' — ' + truncate(parsed.reasoning, 60) : ''), 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }


  function aiFillBrief(contentId) {
    var c = S.contentMap[contentId]; if (!c) return;
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }

    // Expanded brief schema (Phase 3) — asks for any field the user hasn't
    // filled yet. String fields produce a string; array fields produce a
    // list of strings; numeric fields produce a number.
    var bi = c.basic_info || {};
    var r  = c.research || {};
    var isEmpty = function(v) { return v === undefined || v === null || v === '' || (Array.isArray(v) && !v.length); };

    // Field → (needed?, JSON type hint). Pared back in Apr 2026 — CTAs,
    // entities, FAQs, word_count_min/max, SERP competitors, and external
    // references are no longer part of the brief surface.
    var schema = {
      'audience':             { path: 'basic_info.audience',              type: 'string',       empty: isEmpty(bi.audience) },
      'goal':                 { path: 'basic_info.goal',                  type: 'string',       empty: isEmpty(bi.goal) },
      'search_intent':        { path: 'basic_info.search_intent',         type: 'enum:informational|navigational|commercial|transactional', empty: isEmpty(bi.search_intent) },
      'funnel_stage':         { path: 'basic_info.funnel_stage',          type: 'enum:tofu|mofu|bofu', empty: isEmpty(bi.funnel_stage) },
      'content_depth':        { path: 'basic_info.content_depth',         type: 'enum:beginner|intermediate|advanced|expert', empty: isEmpty(bi.content_depth) },
      'tone_of_voice':        { path: 'basic_info.tone_of_voice',         type: 'string',       empty: isEmpty(bi.tone_of_voice) },
      'word_count_target':    { path: 'basic_info.word_count_target',     type: 'number',       empty: isEmpty(bi.word_count_target) },
      'angle':                { path: 'research.selected_angle',          type: 'string',       empty: isEmpty(r.selected_angle) },
      'uvp':                  { path: 'research.uvp',                     type: 'string',       empty: isEmpty(r.uvp) }
    };
    var needs = Object.keys(schema).filter(function(k) { return schema[k].empty; });
    if (!needs.length) { toast('All brief fields already filled — nothing to do', 'info'); return; }

    toast('Filling content brief (' + needs.length + ' fields)…', 'info');
    var ct  = S.contentTypeMap[c.content_type_id];
    var hub = S.hubMap[c.hub_id];
    var cl  = S.clusterMap[c.cluster_id];

    var prompt = 'Fill the missing brief fields for this content piece.\n\n';
    prompt += 'Title: ' + (c.title || '(untitled)') + '\n';
    if (ct)  prompt += 'Content type: ' + ct.name + '\n';
    if (hub) prompt += 'Hub: ' + hub.name + '\n';
    if (cl)  prompt += 'Cluster: ' + cl.name + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nReturn ONLY JSON with these keys:\n';
    for (var ni = 0; ni < needs.length; ni++) {
      var key = needs[ni];
      var info = schema[key];
      prompt += '  ' + key + ' — ';
      if (info.type === 'string')       prompt += 'string (1-2 sentences, plain English)';
      else if (info.type === 'number')  prompt += 'number (integer)';
      else if (info.type === 'array')   prompt += 'array of 3-6 short strings';
      else if (info.type.indexOf('enum:') === 0) prompt += 'one of: ' + info.type.slice(5).replace(/\|/g, ', ');
      prompt += '\n';
    }
    prompt += '\nRespond ONLY as JSON with those keys — no prose, no markdown fences.';

    _wcpAIPreflight.run({
      actionId: 'ai-fill-brief',
      title: 'Fill content brief',
      description: 'AI will fill ' + needs.length + ' missing brief field' + (needs.length !== 1 ? 's' : '') + '.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
        var parsed = parseJSON(text) || {};
        c.basic_info = c.basic_info || {};
        c.research   = c.research   || {};
        var filled = 0;
        for (var k = 0; k < needs.length; k++) {
          var key = needs[k];
          var info = schema[key];
          var val = parsed[key];
          if (val === undefined || val === null || val === '') continue;
          if (info.path.indexOf('basic_info.') === 0) {
            var fld = info.path.split('.')[1];
            if (info.type === 'number') c.basic_info[fld] = parseInt(val, 10) || 0;
            else if (info.type === 'array') c.basic_info[fld] = Array.isArray(val) ? val.slice() : String(val).split(/\n/).map(function(x) { return x.trim(); }).filter(Boolean);
            else c.basic_info[fld] = String(val).trim();
          } else if (info.path.indexOf('research.') === 0) {
            var rfld = info.path.split('.')[1];
            if (info.type === 'array') c.research[rfld] = Array.isArray(val) ? val.slice() : String(val).split(/\n/).map(function(x) { return x.trim(); }).filter(Boolean);
            else c.research[rfld] = String(val).trim();
          }
          filled++;
        }
        c.updated = new Date().toISOString();
        logActivity('ai_action', c.id, c.title, 'AI filled brief (' + filled + ' fields)');
        snapshot('AI fill brief'); maybeAdvanceStatus(c, 'brief filled'); buildMaps(); syncToTextarea(); render();
        toast('Brief filled (' + filled + ' field' + (filled !== 1 ? 's' : '') + ')', 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }
/* ===== 06-ai-actions/03-hub-global.js ===== */
  // ============================================================
  // SECTION 8: AI ACTIONS — HUB, CLUSTER & GLOBAL
  // ============================================================


  // aiSuggestHubs — richer version that returns hub skeletons with suggested
  // clusters, target audience, intent mix, keywords, and strategic rationale.
  // The rendered cards allow either "Quick add" (creates hub + checked
  // clusters in one shot) or "Refine in Wizard" (pipes the suggestion into
  // the New Hub Wizard pre-filled at Step 2 for editing before commit).
  function aiSuggestHubs() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var existing = (S.data.hubs || []).map(function(h) { return h.name; });
    var prompt = 'Suggest 4 to 6 new content hub topics for a website content strategy. Think like a topical-authority strategist: each hub should anchor 5-10 tightly related cluster pages.\n';
    if (existing.length) prompt += 'NEVER suggest these (they already exist): ' + existing.join(', ') + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nFor each hub return:\n';
    prompt += '  - name: short, publishable hub title (2-5 words)\n';
    prompt += '  - description: 2-3 sentence overview of what this hub covers\n';
    prompt += '  - pillar_keyword: the #1 keyword this hub ranks for\n';
    prompt += '  - target_audience: 1 sentence (who is this for?)\n';
    prompt += '  - search_intent_mix: object with approx. fractions summing to 1.0: {"informational":0.6,"commercial":0.3,"transactional":0.1}\n';
    prompt += '  - keywords: array of 3-5 seed topics / secondary keywords\n';
    prompt += '  - rationale: 1 sentence on why this hub fills a coverage gap\n';
    prompt += '  - suggested_clusters: array of 4-5 cluster ideas, each {"name":"...","description":"one sentence","keywords":["...","..."]}\n';
    prompt += '\nRespond ONLY as JSON: {"hubs":[{"name":"...","description":"...","pillar_keyword":"...","target_audience":"...","search_intent_mix":{"informational":0.6,"commercial":0.3,"transactional":0.1},"keywords":["..."],"rationale":"...","suggested_clusters":[{"name":"...","description":"...","keywords":["..."]}]}]}';
    _wcpAIPreflight.run({
      actionId: 'ai-suggest-hubs',
      title: 'Suggest content hubs',
      description: 'AI will propose 4-6 new hub topics with suggested clusters.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var hubs = (parsed.hubs || []).filter(function(h) { return h && h.name; });
        if (!hubs.length) { toast('No hub suggestions returned', 'warning'); return; }
        S._lastHubSuggestions = hubs;
        var html = '<div class="wcp-hub-suggestions">';
        html += '<div class="wcp-text-xs wcp-text-muted" style="margin-bottom:var(--wcp-space-2)">' + icon('circle-info') + ' ' + hubs.length + ' hub idea' + (hubs.length === 1 ? '' : 's') + ' — each has suggested clusters you can include or skip.</div>';
        for (var i = 0; i < hubs.length; i++) html += renderHubSuggestionCard(hubs[i], i);
        html += '</div>';
        openModal('Suggested Hubs', html, { size: 'lg', footer: false });
        logActivity('ai_action', '', '', 'AI suggested ' + hubs.length + ' hubs');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  // Shared hub-suggestion card renderer. Also used by the New Hub Wizard
  // Step 2 to render the AI-generated hub preview + editable cluster list.
  function renderHubSuggestionCard(h, idx) {
    var mix = h.search_intent_mix || {};
    var infoPct = Math.round(((mix.informational || 0) * 100));
    var commPct = Math.round(((mix.commercial    || 0) * 100));
    var transPct = Math.round(((mix.transactional || 0) * 100));
    // Normalise: if any is missing, fill from the rest; if all 0, show 100% info.
    var total = infoPct + commPct + transPct;
    if (total === 0) { infoPct = 100; total = 100; }

    var clusters = Array.isArray(h.suggested_clusters) ? h.suggested_clusters : [];
    var clusterCount = clusters.length;

    var html = '<div class="wcp-hs-card" data-hub-idx="' + idx + '">';

    // Header row
    html += '<div class="wcp-hs-header">';
    html += '<div class="wcp-hs-title-wrap">';
    html += '<div class="wcp-hs-title">' + esc(h.name || '') + '</div>';
    if (h.pillar_keyword) html += '<span class="wcp-badge" style="background:var(--wcp-hub)15;color:var(--wcp-hub)">' + icon('key') + ' ' + esc(h.pillar_keyword) + '</span>';
    if (h.target_audience) html += '<span class="wcp-badge" style="background:var(--wcp-accent)15;color:var(--wcp-accent)">' + icon('users') + ' ' + esc(truncate(h.target_audience, 40)) + '</span>';
    html += '</div></div>';

    // Description + rationale
    if (h.description) html += '<div class="wcp-hs-desc">' + esc(h.description) + '</div>';
    if (h.rationale)   html += '<div class="wcp-hs-rationale">' + icon('lightbulb') + ' ' + esc(h.rationale) + '</div>';

    // Intent mix bar
    if (total > 0) {
      html += '<div class="wcp-hs-intent-mix" title="Search intent mix">';
      html += '<div class="wcp-hs-bar">';
      if (infoPct)  html += '<div class="wcp-hs-bar-seg" style="width:' + infoPct + '%;background:var(--wcp-hub)" title="Informational ' + infoPct + '%"></div>';
      if (commPct)  html += '<div class="wcp-hs-bar-seg" style="width:' + commPct + '%;background:var(--wcp-accent)" title="Commercial ' + commPct + '%"></div>';
      if (transPct) html += '<div class="wcp-hs-bar-seg" style="width:' + transPct + '%;background:var(--wcp-success)" title="Transactional ' + transPct + '%"></div>';
      html += '</div>';
      html += '<div class="wcp-hs-bar-legend">';
      if (infoPct)  html += '<span><span class="wcp-hs-dot" style="background:var(--wcp-hub)"></span>Info ' + infoPct + '%</span>';
      if (commPct)  html += '<span><span class="wcp-hs-dot" style="background:var(--wcp-accent)"></span>Comm ' + commPct + '%</span>';
      if (transPct) html += '<span><span class="wcp-hs-dot" style="background:var(--wcp-success)"></span>Trans ' + transPct + '%</span>';
      html += '</div>';
      html += '</div>';
    }

    // Keyword chips
    if (h.keywords && h.keywords.length) {
      html += '<div class="wcp-hs-keywords">';
      for (var ki = 0; ki < Math.min(h.keywords.length, 6); ki++) {
        html += '<span class="wcp-badge" style="background:var(--wcp-cluster)15;color:var(--wcp-cluster)">' + icon('tag') + ' ' + esc(h.keywords[ki]) + '</span>';
      }
      html += '</div>';
    }

    // Cluster checklist (collapsible when >0)
    if (clusterCount > 0) {
      html += '<details class="wcp-hs-clusters" open>';
      html += '<summary>' + icon('sitemap') + ' Suggested clusters <span class="wcp-hs-count">' + clusterCount + '</span></summary>';
      html += '<div class="wcp-hs-cluster-list">';
      for (var ci = 0; ci < clusters.length; ci++) {
        var cluster = clusters[ci];
        var cluKw = Array.isArray(cluster.keywords) ? cluster.keywords.slice(0, 3).join(', ') : '';
        html += '<label class="wcp-hs-cluster-row">';
        html += '<input type="checkbox" class="wcp-hs-cluster-cb" data-hub-idx="' + idx + '" data-cluster-idx="' + ci + '" checked>';
        html += '<div class="wcp-hs-cluster-body">';
        html += '<div class="wcp-hs-cluster-name">' + esc(cluster.name || '') + '</div>';
        if (cluster.description) html += '<div class="wcp-hs-cluster-desc">' + esc(cluster.description) + '</div>';
        if (cluKw) html += '<div class="wcp-hs-cluster-kw">' + icon('key') + ' ' + esc(cluKw) + '</div>';
        html += '</div></label>';
      }
      html += '</div></details>';
    }

    // Footer: actions
    html += '<div class="wcp-hs-footer">';
    html += '<button class="wcp-btn wcp-btn-sm wcp-btn-outline" data-action="hub-suggest-refine" data-hub-idx="' + idx + '">' + icon('wand-magic-sparkles') + ' Refine in Wizard</button>';
    html += '<button class="wcp-btn wcp-btn-sm wcp-btn-primary" data-action="hub-suggest-quick-add" data-hub-idx="' + idx + '">' + icon('plus') + ' Quick add</button>';
    html += '</div>';

    html += '</div>';
    return html;
  }

  // Export so the wizard can re-render its Step 2 preview with identical styling.
  window._wcpRenderHubSuggestionCard = renderHubSuggestionCard;

  // Fired by the New Hub Wizard at Step 2 transition. Takes the user's own
  // hub name + freeform brief and returns the same rich schema as
  // aiSuggestHubs (a single hub with suggested_clusters). onSuccess is
  // called with the parsed hub object; onError with the error message.
  function aiEnrichHubWithClusters(hubName, initialPrompt, onSuccess, onError) {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); if (onError) onError('no-providers'); return; }

    var existing = (S.data.hubs || []).map(function(h) { return h.name; }).filter(Boolean);
    var prompt = 'You are helping the user create a new content hub for their website.\n\n';
    prompt += 'Hub name (user chose this): ' + (hubName || '') + '\n';
    if (initialPrompt) prompt += 'User brief: ' + initialPrompt + '\n';
    if (existing.length) prompt += 'Existing hubs (for context — do NOT duplicate their scope): ' + existing.join(', ') + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nExpand the hub into full strategic details and propose 5-7 clusters that together cover the hub comprehensively. Each cluster should be a distinct sub-topic that can anchor 3-5 content pieces.\n';
    prompt += '\nReturn a single hub (not an array) with:\n';
    prompt += '  - name: the user-provided hub name (exactly as given)\n';
    prompt += '  - description: 2-3 sentence description\n';
    prompt += '  - pillar_keyword: the #1 SEO keyword for this hub\n';
    prompt += '  - target_audience: 1 sentence describing who this hub serves\n';
    prompt += '  - search_intent_mix: object with approximate fractions summing to 1.0: {"informational":0.6,"commercial":0.3,"transactional":0.1}\n';
    prompt += '  - keywords: array of 5-8 secondary keywords / topic pillars\n';
    prompt += '  - rationale: 1 sentence on why this hub matters strategically\n';
    prompt += '  - suggested_clusters: array of 5-7 cluster ideas, each {"name":"...","description":"one sentence","keywords":["...","..."]}\n';
    prompt += '\nRespond ONLY as JSON: {"hub":{"name":"...","description":"...","pillar_keyword":"...","target_audience":"...","search_intent_mix":{"informational":0.6,"commercial":0.3,"transactional":0.1},"keywords":["..."],"rationale":"...","suggested_clusters":[{"name":"...","description":"...","keywords":["..."]}]}}';

    callAIWithRetry(prompt, function(text) {
      var parsed = parseJSON(text);
      var h = parsed && parsed.hub;
      if (!h || !h.name) { if (onError) onError('no-hub-in-response'); else toast('AI did not return a valid hub', 'error'); return; }
      // Force the user-chosen name to win over any AI drift
      h.name = hubName || h.name;
      if (onSuccess) onSuccess(h);
    }, function(err) {
      if (onError) onError(err);
      else toast('AI Error: ' + err, 'error');
    }, 'ai-enrich-hub', BrandService.getSystemPrompt('research'));
  }

  window._wcpAiEnrichHubWithClusters = aiEnrichHubWithClusters;

  function aiEnrichCluster(clusterId) {
    var cl = S.clusterMap[clusterId]; if (!cl) return;
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var hub = S.hubMap[cl.hub_id];
    var prompt = 'Provide exactly 10 target keywords for this content cluster.\n\nCluster: ' + esc(cl.name) + '\n';
    if (hub) prompt += 'Hub: ' + hub.name + '\n';
    if (cl.keywords && cl.keywords.length) prompt += 'Current keywords (do NOT repeat): ' + cl.keywords.join(', ') + '\n';
    prompt += brandSnippet('seo');
    prompt += '\n\nReturn 10 keywords ranked by SEO value (high commercial intent first, long-tail informational last).\n\nRespond ONLY as JSON: {"keywords":["kw1","kw2","kw3","kw4","kw5","kw6","kw7","kw8","kw9","kw10"]}';
    _wcpAIPreflight.run({
      actionId: 'ai-enrich-cluster',
      title: 'Enrich cluster keywords',
      description: 'AI will return 10 SEO-ranked keywords for "' + (cl.name || 'this cluster') + '".',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('seo'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        if (parsed.keywords && parsed.keywords.length) cl.keywords = parsed.keywords;
        cl.updated = new Date().toISOString();
        logActivity('cluster_updated', cl.id, cl.name, 'AI enriched cluster');
        snapshot('AI enrich cluster'); buildMaps(); syncToTextarea(); render();
        toast('Cluster enriched with ' + (parsed.keywords || []).length + ' keywords', 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function aiSuggestTags() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    // Step 1: Show options modal
    var optHtml = '<div class="wcp-editor-form">';
    optHtml += '<div class="wcp-form-group"><label>Number of Tags</label><select class="wcp-select" data-field="count">';
    [5, 10, 15].forEach(function(n) { optHtml += '<option value="' + n + '"' + (n === 10 ? ' selected' : '') + '>' + n + ' tags</option>'; });
    optHtml += '</select></div>';
    optHtml += '<div class="wcp-form-group"><label>Focus Area (optional)</label><input type="text" class="wcp-input" data-field="focus" placeholder="e.g. content lifecycle, difficulty levels, topic areas..."></div>';
    optHtml += '</div>';
    openModal('AI Tag Suggestions', optHtml, {
      saveLabel: icon('sparkles') + ' Generate',
      onSave: function() {
        var f = collectModalFields();
        var count = parseInt(f.count, 10) || 10;
        var focus = f.focus || '';
        closeModal();
        _runTagSuggestion(count, focus);
      }
    });
  }

  function _runTagSuggestion(count, focus) {
    var existing = (S.data.tags || []).map(function(t) { return t.name; }).join(', ');
    var contentTitles = (S.data.content || []).map(function(c) { return c.title; }).slice(0, 10).join('; ');
    var prompt = 'Suggest ' + count + ' organizational tags.\n\n';
    if (existing) prompt += 'Do NOT duplicate these existing tags: ' + existing + '\n';
    if (contentTitles) prompt += 'Sample content titles: ' + contentTitles + '\n';
    if (focus) prompt += 'Focus area: ' + focus + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nGroup tags by category. Each tag must be reusable across multiple content pieces.\n\nRespond ONLY as JSON: {"tags":[{"name":"Tag Name","group":"Category","description":"1 sentence"}]}';
    _wcpAIPreflight.run({
      actionId: 'ai-suggest-tags',
      title: 'Suggest tags',
      description: 'AI will generate ' + count + ' organizational tag' + (count !== 1 ? 's' : '') + (focus ? ' (focus: ' + focus + ')' : '') + '.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
      var parsed = parseJSON(text);
      var suggestions = parsed.tags || [];
      if (!suggestions.length) { toast('No tag suggestions generated', 'warning'); return; }
      // Step 2: Show selection modal
      var selHtml = '<div class="wcp-editor-form">';
      selHtml += '<p class="wcp-text-sm wcp-text-muted" style="margin-bottom:var(--wcp-space-3)">Select the tags you want to create. Uncheck any you don\'t need.</p>';
      for (var i = 0; i < suggestions.length; i++) {
        var tg = suggestions[i];
        selHtml += '<label class="wcp-radio-item" style="cursor:pointer;display:flex;align-items:flex-start;gap:var(--wcp-space-2);padding:var(--wcp-space-2) var(--wcp-space-3);border:1px solid var(--wcp-border-light);border-radius:var(--wcp-radius-md);margin-bottom:var(--wcp-space-2)">';
        selHtml += '<input type="checkbox" class="wcp-tag-select" data-tag-idx="' + i + '" checked style="margin-top:3px;flex-shrink:0">';
        selHtml += '<div style="flex:1;min-width:0">';
        selHtml += '<div style="font-weight:600;font-size:var(--wcp-font-size-sm)">' + esc(tg.name || '') + '</div>';
        selHtml += '<div style="display:flex;gap:var(--wcp-space-1);margin-top:2px">' + badge(tg.group || 'General', 'var(--wcp-accent)') + '</div>';
        if (tg.description) selHtml += '<div class="wcp-text-sm wcp-text-muted" style="margin-top:2px">' + esc(tg.description) + '</div>';
        selHtml += '</div></label>';
      }
      selHtml += '</div>';
      openModal('Select Tags to Create (' + suggestions.length + ' suggested)', selHtml, {
        size: 'lg',
        saveLabel: icon('check') + ' Create Selected Tags',
        onSave: function() {
          var created = 0;
          S.data.tags = S.data.tags || [];
          $('.wcp-tag-select:checked').each(function() {
            var idx = parseInt($(this).data('tag-idx'), 10);
            var tg = suggestions[idx];
            if (!tg || !tg.name) return;
            // Check if tag already exists
            var exists = S.data.tags.some(function(t) { return t.name.toLowerCase() === tg.name.toLowerCase(); });
            if (exists) return;
            var colorIdx = (S.data.tags.length + created) % Constants.HUB_COLORS.length;
            S.data.tags.push({
              id: generateId('tag'),
              name: tg.name.trim(),
              color: Constants.HUB_COLORS[colorIdx].color,
              group: (tg.group || 'General').trim(),
              description: tg.description || '',
              created: new Date().toISOString()
            });
            created++;
          });
          if (created > 0) {
            logActivity('ai_action', '', '', 'AI created ' + created + ' tags');
            snapshot('AI create tags'); buildMaps(); closeModal(); syncToTextarea(); render();
            toast('Created ' + created + ' tags', 'success');
          } else {
            closeModal();
            toast('No new tags created (all already exist or none selected)', 'info');
          }
        }
      });
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function aiBuildTemplate() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var types = (S.data.content_types || []).map(function(t) { return t.name; }).join(', ');
    var prompt = 'Create a content template with exactly 5 sections.\n';
    if (types) prompt += 'Available content types: ' + types + '\n';
    prompt += brandSnippet('content');
    prompt += '\n\nEach section needs: name (short), instructions (1-2 sentences telling the writer what to do).\nThe Template editor lets the user fill heading_level / section_type / est_words later — keep this output lean.\n\nRespond ONLY as JSON: {"name":"Template Name","content_type":"matching type from list above","description":"1 sentence","sections":[{"name":"Section Name","instructions":"writing instructions"}]}';
    _wcpAIPreflight.run({
      actionId: 'ai-build-template',
      title: 'Build content template',
      description: 'AI will draft a 5-section content template.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var tplName = parsed.name || 'AI Template';
        var tplDesc = parsed.description || '';
        var sections = (parsed.sections || []).map(function(s) {
          return { name: s.name || '', instructions: s.instructions || '', heading_level: 'H2', section_type: 'body', est_words: 200 };
        });
        if (!sections.length) { toast('AI returned no sections', 'warning'); return; }
        // Preview modal — let user edit name/description, deselect sections, then save.
        var html = '<div class="wcp-editor-form">';
        html += '<div class="wcp-form-group"><label>Template Name</label>';
        html += '<input type="text" class="wcp-input" data-field="tplName" value="' + esc(tplName) + '"></div>';
        html += '<div class="wcp-form-group"><label>Description</label>';
        html += '<input type="text" class="wcp-input" data-field="tplDesc" value="' + esc(tplDesc) + '"></div>';
        html += '<div class="wcp-form-group"><label>Sections (' + sections.length + ' suggested) <span class="wcp-form-hint">— uncheck any you don\'t want</span></label>';
        html += '<div style="display:flex;flex-direction:column;gap:var(--wcp-space-2);max-height:340px;overflow:auto;padding:var(--wcp-space-2);background:var(--wcp-gray-50);border-radius:var(--wcp-radius-md)">';
        for (var si = 0; si < sections.length; si++) {
          var s = sections[si];
          html += '<label style="display:flex;align-items:flex-start;gap:var(--wcp-space-2);padding:var(--wcp-space-2);background:var(--wcp-white);border:1px solid var(--wcp-border-light);border-radius:var(--wcp-radius-sm);cursor:pointer">';
          html += '<input type="checkbox" class="wcp-tpl-section-cb" data-idx="' + si + '" checked style="margin-top:3px;flex-shrink:0">';
          html += '<div style="flex:1;min-width:0">';
          html += '<div style="font-weight:600;font-size:var(--wcp-font-size-sm)">' + esc(s.name) + '</div>';
          if (s.instructions) html += '<div class="wcp-text-xs wcp-text-muted" style="margin-top:2px">' + esc(s.instructions) + '</div>';
          html += '</div></label>';
        }
        html += '</div></div>';
        html += '</div>';
        openModal('Preview Template — ' + esc(tplName), html, {
          size: 'lg',
          saveLabel: icon('check') + ' Create Template',
          onSave: function() {
            var f = collectModalFields();
            var finalName = (f.tplName || tplName).trim() || 'AI Template';
            var finalDesc = (f.tplDesc || tplDesc).trim();
            var finalSections = [];
            $('.wcp-tpl-section-cb:checked').each(function() {
              var idx = parseInt($(this).data('idx'), 10);
              if (sections[idx]) finalSections.push(sections[idx]);
            });
            if (!finalSections.length) { toast('Select at least one section', 'warning'); return; }
            var tpl = {
              id: generateId('tpl'), name: finalName,
              content_type_id: '', description: finalDesc, uses_count: 0,
              sections: finalSections
            };
            S.data.templates = S.data.templates || [];
            S.data.templates.push(tpl);
            logActivity('template_created', tpl.id, tpl.name, 'AI built template with ' + tpl.sections.length + ' sections');
            snapshot('AI template'); buildMaps(); syncToTextarea();
            closeModal();
            render();
            toast('Template "' + tpl.name + '" created with ' + tpl.sections.length + ' section' + (tpl.sections.length !== 1 ? 's' : ''), 'success');
          }
        });
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  // aiSuggestContent — per-cluster content idea generation.
  //
  // Fires from the "Suggest" button on each cluster card in the Hubs view.
  // Two-phase behaviour:
  //   1. If the cluster already has persisted suggestions, open the panel
  //      immediately so the user sees their prior list (adopted + unused).
  //   2. Otherwise, call the LLM, APPEND the result objects onto
  //      cluster.ai_suggestions (dedup by title), persist, open the panel.
  //
  // Suggestions are stored as full objects (not just titles) so the user can
  // return to the panel, delete individual rows, or adopt more without
  // regenerating. Each suggestion carries a stable `id` so the adopt /
  // delete handlers can target it.
  function aiSuggestContent(clusterId) {
    var cl = S.clusterMap[clusterId]; if (!cl) return;
    cl.ai_suggestions = Array.isArray(cl.ai_suggestions) ? cl.ai_suggestions : [];

    // Phase 1 — just show the panel if there's already something to review.
    if (cl.ai_suggestions.length > 0) {
      openClusterSuggestionsPanel(clusterId);
      return;
    }

    // Phase 2 — cold generation.
    _runClusterSuggestionGeneration(cl, { onComplete: function() { openClusterSuggestionsPanel(clusterId); } });
  }

  // Internal: fire the LLM call and append results to cluster.ai_suggestions.
  // Used both by cold generation (aiSuggestContent with empty list) and by
  // the "Generate more" button on the panel.
  function _runClusterSuggestionGeneration(cl, opts) {
    opts = opts || {};
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var hub = S.hubMap[cl.hub_id];

    // Dedup context: existing content titles in this cluster + titles of
    // suggestions we already have on record (regardless of used/unused).
    var existingContent = getClusterContent(cl.id).map(function(c) { return c.title; }).filter(Boolean);
    var priorTitles = (cl.ai_suggestions || []).map(function(s) { return s.title; }).filter(Boolean);
    // Back-compat with the legacy string-only stash that some clusters may
    // still carry from before the full-object shape existed.
    var legacy = (cl.ai_suggested_titles || []).slice(-20);
    var dedupList = existingContent.concat(priorTitles).concat(legacy);

    var prompt = 'Suggest 6 new content pieces for this cluster. Each must be distinct, specific, and fill a real gap.\n\n';
    prompt += 'Cluster: ' + (cl.name || '') + '\n';
    if (cl.keywords && cl.keywords.length) {
      var kwNames = cl.keywords.map(function(k) { return typeof k === 'string' ? k : (k.keyword || ''); }).filter(Boolean).join(', ');
      if (kwNames) prompt += 'Target keywords: ' + kwNames + '\n';
    }
    if (hub) {
      prompt += 'Hub: ' + hub.name;
      if (hub.pillar_keyword) prompt += ' (pillar keyword: ' + hub.pillar_keyword + ')';
      prompt += '\n';
    }
    if (dedupList.length) prompt += 'Already covered (do NOT duplicate or rephrase these): ' + dedupList.join('; ') + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nFor each suggestion return:\n';
    prompt += '  - title: specific, publishable headline (6-12 words)\n';
    prompt += '  - search_intent: one of informational / commercial / transactional / navigational\n';
    prompt += '  - content_type: one of Blog Post, Ultimate Guide, Landing Page, Case Study, Comparison, How-To\n';
    prompt += '  - keywords: array of 3-5 target keywords this piece should rank for\n';
    prompt += '  - rationale: 1 short sentence on why this fills a gap\n';
    prompt += '\nRespond ONLY as JSON: {"ideas":[{"title":"...","search_intent":"...","content_type":"...","keywords":["...","..."],"rationale":"..."}]}';

    _wcpAIPreflight.run({
      actionId: 'ai-suggest-content',
      title: 'Suggest content ideas',
      description: 'AI will propose 6 new content ideas for "' + (cl.name || 'this cluster') + '".',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var ideas = (parsed.ideas || []).filter(function(x) { return x && x.title; });
        if (!ideas.length) { toast('No ideas returned', 'warning'); return; }

        var knownLc = {};
        cl.ai_suggestions.forEach(function(s) { if (s && s.title) knownLc[s.title.toLowerCase()] = true; });
        (cl.ai_suggested_titles || []).forEach(function(t) { if (t) knownLc[(t + '').toLowerCase()] = true; });

        var now = new Date().toISOString();
        var added = 0;
        for (var i = 0; i < ideas.length; i++) {
          var idea = ideas[i];
          var key = (idea.title || '').toLowerCase();
          if (!key || knownLc[key]) continue;
          knownLc[key] = true;
          cl.ai_suggestions.push({
            id: generateId('sg'),
            title: idea.title,
            search_intent: idea.search_intent || '',
            content_type: idea.content_type || '',
            keywords: Array.isArray(idea.keywords) ? idea.keywords.slice() : [],
            rationale: idea.rationale || '',
            created: now,
            used_content_id: null
          });
          added++;
        }

        cl.ai_suggested_titles = (cl.ai_suggested_titles || []).concat(ideas.map(function(i) { return i.title; })).slice(-40);
        cl.updated = now;
        buildMaps(); syncToTextarea();

        logActivity('ai_action', cl.id, cl.name, 'AI suggested ' + added + ' content ideas (' + (ideas.length - added) + ' duplicates skipped)');
        toast('Added ' + added + ' idea' + (added === 1 ? '' : 's') + ' to "' + truncate(cl.name, 24) + '"', 'success');
        if (opts.onComplete) opts.onComplete();
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  // Render the Suggestions panel. Uses a modal shell but rebuilds the body
  // in place (no close-on-adopt) so the user can adopt multiple suggestions
  // back-to-back. Adoption marks a row as Used; the row stays visible with a
  // green "Used" chip linking to the new content.
  function openClusterSuggestionsPanel(clusterId) {
    var cl = S.clusterMap[clusterId]; if (!cl) return;
    cl.ai_suggestions = Array.isArray(cl.ai_suggestions) ? cl.ai_suggestions : [];
    openModal('Content Ideas — ' + esc(cl.name), renderClusterSuggestionsPanelBody(cl), {
      size: 'lg',
      footer: false,
      dataCluster: cl.id   // consumed by the re-render helper (see below)
    });
  }

  // Rebuild just the inner body — used after adopt / delete / generate-more
  // to refresh counts + rows without destroying the modal shell.
  function refreshClusterSuggestionsPanel(clusterId) {
    var cl = S.clusterMap[clusterId]; if (!cl) return;
    var $body = $('.wcp-modal .wcp-modal-body .wcp-cluster-suggestions');
    if (!$body.length) return;  // modal not open
    $body.replaceWith(renderClusterSuggestionsPanelBody(cl));
  }

  function renderClusterSuggestionsPanelBody(cl) {
    var all = cl.ai_suggestions || [];
    var unused = all.filter(function(s) { return !s.used_content_id; });
    var used   = all.filter(function(s) { return  s.used_content_id; });
    var html = '<div class="wcp-cluster-suggestions">';

    // Header strip with counts + actions
    html += '<div class="wcp-cs-header">';
    html += '<div class="wcp-cs-counts">';
    html += '<span class="wcp-badge" style="background:var(--wcp-gray-100);color:var(--wcp-text-secondary)">' + icon('sparkles') + ' ' + all.length + ' total</span>';
    html += '<span class="wcp-badge" style="background:var(--wcp-accent)15;color:var(--wcp-accent)">' + unused.length + ' unused</span>';
    if (used.length) html += '<span class="wcp-badge" style="background:var(--wcp-success)15;color:var(--wcp-success)">' + icon('check') + ' ' + used.length + ' used</span>';
    html += '</div>';
    html += '<div class="wcp-cs-actions">';
    html += '<button class="wcp-btn-ai wcp-btn-ai-sm" data-action="cluster-suggest-more" data-cluster="' + esc(cl.id) + '">' + icon('sparkles') + ' Generate more</button>';
    if (all.length) html += '<button class="wcp-btn wcp-btn-sm wcp-btn-outline" data-action="cluster-suggest-clear" data-cluster="' + esc(cl.id) + '" style="color:var(--wcp-error);border-color:var(--wcp-error)">' + icon('trash') + ' Clear all</button>';
    html += '</div>';
    html += '</div>';

    // Empty state
    if (!all.length) {
      html += '<div class="wcp-empty-state" style="padding:24px 12px">';
      html += '<div class="wcp-empty-state-icon">' + icon('sparkles') + '</div>';
      html += '<div class="wcp-empty-state-title">No suggestions yet</div>';
      html += '<div class="wcp-empty-state-text">Click <strong>Generate more</strong> to get 6 AI-generated content ideas for this cluster.</div>';
      html += '</div></div>';
      return html;
    }

    // Unused first
    if (unused.length) {
      for (var i = 0; i < unused.length; i++) html += renderSuggestionRow(unused[i], cl, false);
    }
    // Then used (dimmed, with green tick)
    if (used.length) {
      html += '<div class="wcp-cs-divider">Previously used (' + used.length + ')</div>';
      for (var j = 0; j < used.length; j++) html += renderSuggestionRow(used[j], cl, true);
    }

    html += '</div>';
    return html;
  }

  function renderSuggestionRow(s, cl, isUsed) {
    var intentClr = { 'informational': 'var(--wcp-hub)', 'commercial': 'var(--wcp-accent)', 'transactional': 'var(--wcp-success)', 'navigational': 'var(--wcp-warning)' }[s.search_intent] || 'var(--wcp-text-muted)';
    var kwJson = esc(JSON.stringify(s.keywords || []));
    var html = '<div class="wcp-cs-row' + (isUsed ? ' wcp-cs-row-used' : '') + '" data-sid="' + esc(s.id) + '">';
    html += '<div class="wcp-cs-body">';
    html += '<div class="wcp-cs-title">' + esc(s.title || '') + '</div>';
    if (s.rationale) html += '<div class="wcp-cs-rationale">' + esc(s.rationale) + '</div>';
    html += '<div class="wcp-cs-meta">';
    if (s.search_intent) html += '<span class="wcp-badge" style="background:' + intentClr + '20;color:' + intentClr + '">' + icon('compass') + ' ' + esc(s.search_intent) + '</span>';
    if (s.content_type)  html += '<span class="wcp-badge" style="background:var(--wcp-gray-100);color:var(--wcp-text-secondary)">' + esc(s.content_type) + '</span>';
    if (s.keywords && s.keywords.length) {
      for (var ki = 0; ki < Math.min(s.keywords.length, 4); ki++) {
        html += '<span class="wcp-badge" style="background:var(--wcp-cluster)15;color:var(--wcp-cluster)">' + icon('key') + ' ' + esc(s.keywords[ki]) + '</span>';
      }
    }
    html += '</div></div>';

    html += '<div class="wcp-cs-actions-col">';
    if (isUsed) {
      var usedContent = S.contentMap && S.contentMap[s.used_content_id];
      if (usedContent) {
        html += '<button class="wcp-btn wcp-btn-sm wcp-btn-success-solid" data-action="cluster-suggest-open-used" data-content="' + esc(s.used_content_id) + '" title="Open the content this idea became">' + icon('check') + ' Used &rarr;</button>';
      } else {
        html += '<span class="wcp-badge" style="background:var(--wcp-gray-100);color:var(--wcp-text-secondary)" title="The adopted content was deleted">' + icon('check') + ' Used (removed)</span>';
      }
    } else {
      html += '<button class="wcp-btn wcp-btn-sm wcp-btn-primary" data-action="adopt-suggestion" data-sid="' + esc(s.id) + '" data-title="' + esc(s.title || '') + '" data-hub="' + esc(cl.hub_id || '') + '" data-cluster="' + esc(cl.id) + '" data-intent="' + esc(s.search_intent || '') + '" data-type="' + esc(s.content_type || '') + '" data-keywords="' + kwJson + '">' + icon('plus') + ' Adopt</button>';
      html += '<button class="wcp-btn-delete-sm" data-action="cluster-suggest-delete" data-cluster="' + esc(cl.id) + '" data-sid="' + esc(s.id) + '" title="Delete this suggestion">' + icon('trash') + '</button>';
    }
    html += '</div></div>';
    return html;
  }

  // Exported for the wizard + events (see part2b/14-events.js).
  window._wcpOpenClusterSuggestionsPanel = openClusterSuggestionsPanel;
  window._wcpRefreshClusterSuggestionsPanel = refreshClusterSuggestionsPanel;
  window._wcpRunClusterSuggestionGeneration = _runClusterSuggestionGeneration;

  function aiPlanCalendar(hubId) {
    var hub = S.hubMap[hubId]; if (!hub) return;
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var content = getHubContent(hubId);
    var existingTitles = content.map(function(c) { return c.title; }).slice(0, 10).join('; ');
    var prompt = 'Plan an 8-item content calendar for this hub spread over 4 weeks (2 items/week).\n\n';
    prompt += 'Hub: ' + esc(hub.name) + '\n';
    if (existingTitles) prompt += 'Existing content (do not duplicate): ' + existingTitles + '\n';
    prompt += brandSnippet('seo');
    prompt += '\n\nProduce 8 publishable items. Sequence them so high-priority commercial pieces ship first, then supporting informational pieces.\n\nRespond ONLY as JSON: {"items":[{"week":1,"title":"specific title","content_type":"Blog Post|Guide|Landing Page|Case Study|Comparison|How-To|Tool","priority":"high|medium|low","rationale":"1 sentence on why this fits"}]}';
    _wcpAIPreflight.run({
      actionId: 'ai-plan-calendar',
      title: 'Plan content calendar',
      description: 'AI will plan an 8-item, 4-week calendar for hub "' + (hub.name || '') + '".',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var items = parsed.items || [];
        if (!items.length) { toast('No calendar items returned', 'warning'); return; }
        // Stash items so the "Adopt selected" save handler can read them by index.
        S._lastCalendarPlan = { hubId: hubId, items: items };
        var html = '<div class="wcp-editor-form">';
        html += '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:var(--wcp-space-2);font-size:var(--wcp-font-size-sm)">';
        html += '<label style="cursor:pointer"><input type="checkbox" id="wcpCalAll" checked> Select all (' + items.length + ')</label>';
        html += '<span class="wcp-text-xs wcp-text-muted">Selected items will be created as content under this hub</span>';
        html += '</div>';
        html += '<table style="width:100%;border-collapse:collapse;font-size:var(--wcp-font-size-sm)">';
        html += '<thead><tr style="background:var(--wcp-gray-50);text-align:left">';
        html += '<th style="padding:8px;border-bottom:1px solid var(--wcp-border-light);width:40px"></th>';
        html += '<th style="padding:8px;border-bottom:1px solid var(--wcp-border-light)">Week</th>';
        html += '<th style="padding:8px;border-bottom:1px solid var(--wcp-border-light)">Title</th>';
        html += '<th style="padding:8px;border-bottom:1px solid var(--wcp-border-light)">Type</th>';
        html += '<th style="padding:8px;border-bottom:1px solid var(--wcp-border-light)">Priority</th>';
        html += '</tr></thead><tbody>';
        for (var i = 0; i < items.length; i++) {
          var it = items[i];
          var prClr = it.priority === 'high' ? 'var(--wcp-error)' : (it.priority === 'medium' ? 'var(--wcp-warning)' : 'var(--wcp-text-muted)');
          html += '<tr style="border-bottom:1px solid var(--wcp-border-light)">';
          html += '<td style="padding:8px;text-align:center"><input type="checkbox" class="wcp-cal-item-cb" data-idx="' + i + '" checked></td>';
          html += '<td style="padding:8px;font-weight:600">W' + esc(it.week || '?') + '</td>';
          html += '<td style="padding:8px"><strong>' + esc(it.title || '') + '</strong>';
          if (it.rationale) html += '<div class="wcp-text-xs wcp-text-muted">' + esc(it.rationale) + '</div>';
          html += '</td>';
          html += '<td style="padding:8px">' + esc(it.content_type || '—') + '</td>';
          html += '<td style="padding:8px"><span class="wcp-badge" style="background:' + prClr + '20;color:' + prClr + '">' + esc(it.priority || 'medium') + '</span></td>';
          html += '</tr>';
        }
        html += '</tbody></table></div>';
        openModal('Content Calendar — ' + esc(hub.name), html, {
          size: 'lg',
          saveLabel: icon('check') + ' Adopt selected',
          onSave: function() {
            var pickedIdx = [];
            $('.wcp-cal-item-cb:checked').each(function() {
              pickedIdx.push(parseInt($(this).data('idx'), 10));
            });
            if (!pickedIdx.length) { toast('Select at least one item', 'warning'); return; }
            snapshot('Adopt calendar items');
            var created = 0;
            for (var j = 0; j < pickedIdx.length; j++) {
              var it = items[pickedIdx[j]];
              if (!it || !it.title) continue;
              var cnt = createContent({ title: it.title, hub_id: hubId, cluster_id: '' });
              cnt.basic_info = cnt.basic_info || {};
              if (it.content_type) {
                var matched = (S.data.content_types || []).find(function(t) { return (t.name || '').toLowerCase() === (it.content_type || '').toLowerCase(); });
                if (matched) cnt.content_type_id = matched.id;
              }
              if (it.priority) cnt.priority = it.priority;
              created++;
            }
            buildMaps(); syncToTextarea();
            closeModal();
            render();
            toast('Created ' + created + ' content piece' + (created !== 1 ? 's' : '') + ' from calendar', 'success');
          }
        });
        // Wire up "Select all" toggle for this modal (idempotent — replaces any previous binding).
        $(document).off('change.wcpCalAll').on('change.wcpCalAll', '#wcpCalAll', function() {
          $('.wcp-cal-item-cb').prop('checked', this.checked);
        });
        logActivity('ai_action', hub.id, hub.name, 'AI planned calendar (' + items.length + ' items)');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }
/* ===== 06-ai-actions/04-suggest-links.js ===== */
  // ============================================================
  // SECTION 8B: AI SUGGEST INTERNAL LINKS
  // ============================================================
  //
  // Hybrid engine: rule scoring shortlists top-20 candidates, then the LLM
  // ranks the best ~8 with anchor text + reason. When no AI is configured,
  // falls back to rule-only suggestions (still useful for new setups).
  //
  // Suggestions live on S.linkSuggestions[contentId] — transient, not
  // persisted. Committing a suggestion creates a ledger record via
  // createSitemapLink (exposed as window._wcpCreateSitemapLink).

  function suggestInternalLinks(contentId) {
    var c = S.contentMap[contentId]; if (!c) return;
    var sm = (S.data.sitemap) || { pages: [] };
    if (!sm.pages || !sm.pages.length) {
      toast('Import your sitemap first — no pages to link to', 'warning');
      return;
    }

    // Rule phase (always runs). Lowered minScore to 1 so weak title/path
    // overlaps still surface — the AI phase will re-rank and prune.
    var scoreFn = window._wcpScoreSitemapPagesForContent;
    var candidates = scoreFn ? scoreFn(c, { topN: 25, minScore: 1 }) : [];
    if (!candidates.length) {
      // Explain exactly what's missing so the user knows how to unblock.
      var why = (typeof window._wcpExplainNoLinkCandidates === 'function')
        ? window._wcpExplainNoLinkCandidates(c)
        : 'No relevant pages found.';
      // Render an inline hint in the picker (via transient suggestions marker) + toast
      S.linkSuggestions = S.linkSuggestions || {};
      S.linkSuggestions[contentId] = [];
      S._linkSuggestionHint = S._linkSuggestionHint || {};
      S._linkSuggestionHint[contentId] = why;
      _rerenderLinkPickerSection(contentId);
      toast('No link candidates yet — see the picker for details', 'info');
      return;
    }
    // Clear any stale "no candidates" hint now that we have matches
    if (S._linkSuggestionHint) delete S._linkSuggestionHint[contentId];

    // If AI isn't configured, render rule-only suggestions and stop.
    if (!LLMService.isConfigured()) {
      var fallback = candidates.slice(0, 10).map(function(r) {
        return {
          page_id: r.page.id,
          anchor_text: '',
          reason: r.reasons.join(' · '),
          score: r.score,
          confidence: Math.min(1, r.score / 100),
          source: 'rule'
        };
      });
      S.linkSuggestions = S.linkSuggestions || {};
      S.linkSuggestions[contentId] = fallback;
      _rerenderLinkPickerSection(contentId);
      toast('Rule-based suggestions ready (' + fallback.length + ') — configure AI for smarter ranking', 'info');
      return;
    }

    // AI phase — rank the top 20 and return the best 8 with anchor + reason.
    var ct  = S.contentTypeMap[c.content_type_id];
    var hub = S.hubMap[c.hub_id];
    var cl  = S.clusterMap[c.cluster_id];
    var bi  = c.basic_info || {};

    var prompt = 'Pick the best internal links for this new content piece from the candidate list.\n\n';
    prompt += '=== NEW CONTENT ===\n';
    prompt += 'Title: ' + (c.title || '(untitled)') + '\n';
    if (ct)  prompt += 'Type: ' + ct.name + '\n';
    if (hub) prompt += 'Hub: ' + hub.name + '\n';
    if (cl)  prompt += 'Cluster: ' + cl.name + '\n';
    if (bi.audience) prompt += 'Audience: ' + bi.audience + '\n';
    if (bi.search_intent) prompt += 'Intent: ' + bi.search_intent + '\n';
    var r = c.research || {};
    if (r.selected_angle) prompt += 'Angle: ' + r.selected_angle + '\n';
    if (r.uvp) prompt += 'UVP: ' + r.uvp + '\n';

    prompt += '\n=== CANDIDATE PAGES (id, title, url, priority) ===\n';
    for (var i = 0; i < candidates.length; i++) {
      var p = candidates[i].page;
      var eff = (typeof window._wcpEffectivePriority === 'function') ? window._wcpEffectivePriority(p) : 3;
      prompt += (i + 1) + '. id="' + p.id + '" | P' + eff + ' | ' + (p.title || '(untitled)') + ' — ' + p.url + '\n';
    }
    prompt += brandSnippet('content');

    prompt += '\n\nPick 5-8 links that would genuinely help this content\'s reader. For each, write:\n';
    prompt += '  - page_id: exact id from the list\n';
    prompt += '  - reason: 1 sentence on *why* this link helps the reader\n';
    prompt += '  - confidence: 0.0 to 1.0\n';
    prompt += '\nPrefer P1/P2 pages when relevance is similar. Avoid forced links. The writer will write their own anchor text — do NOT provide anchor text.\n';
    prompt += '\nRespond ONLY as JSON: {"links":[{"page_id":"sp_xxx","reason":"...","confidence":0.9}]}';

    _wcpAIPreflight.run({
      actionId: 'ai-suggest-links',
      title: 'Suggest internal links',
      description: 'AI will rank ' + candidates.length + ' candidate page' + (candidates.length !== 1 ? 's' : '') + ' and pick the 5-8 most relevant.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var ranked = (parsed.links || []).filter(function(x) { return x && x.page_id; });
        var out = [];
        for (var k = 0; k < ranked.length; k++) {
          var rk = ranked[k];
          var match = null;
          for (var m = 0; m < candidates.length; m++) {
            if (candidates[m].page.id === rk.page_id) { match = candidates[m]; break; }
          }
          if (!match) continue;
          out.push({
            page_id: rk.page_id,
            anchor_text: '',
            reason: rk.reason || match.reasons.join(' · '),
            score: match.score,
            confidence: typeof rk.confidence === 'number' ? rk.confidence : 0.7,
            source: 'ai'
          });
        }
        S.linkSuggestions = S.linkSuggestions || {};
        S.linkSuggestions[contentId] = out;
        logActivity('ai_action', c.id, c.title, 'AI suggested ' + out.length + ' internal links');
        _rerenderLinkPickerSection(contentId);
        toast('AI suggested ' + out.length + ' link' + (out.length !== 1 ? 's' : ''), 'success');
      },
      onError: function(err) {
        toast('AI Error: ' + err, 'error');
        var fallback2 = candidates.slice(0, 10).map(function(rr) {
          return { page_id: rr.page.id, anchor_text: '', reason: rr.reasons.join(' · '), score: rr.score, confidence: 0.5, source: 'rule' };
        });
        S.linkSuggestions = S.linkSuggestions || {};
        S.linkSuggestions[contentId] = fallback2;
        _rerenderLinkPickerSection(contentId);
      }
    });
  }

  // Swap only the link picker section's DOM — keeps scroll position and
  // avoids clobbering any user input elsewhere in the brief.
  function _rerenderLinkPickerSection(contentId) {
    if (typeof window._wcpRenderLinkPicker !== 'function') { if (render) render(); return; }
    var html = window._wcpRenderLinkPicker(contentId);
    var $slot = $('#wcpLinkPicker_' + contentId);
    if ($slot.length) $slot.replaceWith(html);
    else if (render) render();
  }

  // Expose to Part 2A's event wiring
  window._wcpSuggestInternalLinks = suggestInternalLinks;
/* ===== 06-ai-actions/05-content-wizard.js ===== */
  // ============================================================
  // SECTION 8.5: AI ACTION — DRAFT CONTENT BRIEF (NEW CONTENT WIZARD)
  // ============================================================
  //
  // Single LLM call that takes the wizard's user-provided brief (+ the
  // fetched/pasted article body if mode === 'refresh') and returns a rich
  // draft of the whole content record: title, content_type, hub/cluster
  // suggestion (matched against existing ids), basic_info, keywords, research
  // angles, audience, goal, word-count band.
  //
  // The wizard renders the response as an editable preview; on commit, the
  // payload is merged into createContent() plus a linked keyword group.
  //
  // Signature:
  //   aiDraftContentBrief(input, onSuccess, onError)
  // where input = {
  //   mode: 'new' | 'refresh',
  //   userBrief: { title, topic, audience, goal, hub_id, cluster_id, priority },
  //   source?: { url, title, body }   // refresh mode only
  // }
  // onSuccess(draft) — draft is the parsed hub object
  // onError(errMsg)  — toasts already fired by LLMService

  function aiDraftContentBrief(input, onSuccess, onError) {
    if (!LLMService.isConfigured()) {
      toast('No AI providers configured', 'warning');
      if (onError) onError('no-providers');
      return;
    }
    input = input || {};
    var mode = input.mode === 'refresh' ? 'refresh' : 'new';
    var u = input.userBrief || {};
    var src = input.source || {};

    // Pull existing hubs + clusters so the AI can match by ID. Only supply
    // candidates with names filled so the model has something to reason about.
    var hubs = (S.data.hubs || []).filter(function(h) { return h && h.name; }).map(function(h) {
      return { id: h.id, name: h.name, pillar_keyword: h.pillar_keyword || '', description: (h.description || '').substring(0, 140) };
    });
    var clusters = (S.data.clusters || []).filter(function(c) { return c && c.name; }).map(function(c) {
      return { id: c.id, hub_id: c.hub_id || '', name: c.name, description: (c.description || '').substring(0, 120) };
    });
    var types = (S.data.content_types || []).map(function(t) { return t.name; }).filter(Boolean);

    var prompt = '';
    if (mode === 'refresh') {
      prompt += 'You are helping refresh an existing piece of content. Analyse the page text below and draft an updated content brief that improves on it.\n\n';
      prompt += 'Existing URL: ' + (src.url || '(not provided)') + '\n';
      if (src.title) prompt += 'Existing title: ' + src.title + '\n';
      if (src.body)  prompt += 'Existing page text (truncated):\n"""\n' + src.body.substring(0, 6000) + '\n"""\n';
    } else {
      prompt += 'You are helping create a brand-new piece of content. Draft a complete content brief from the user input below.\n\n';
    }

    prompt += '\nUser input:\n';
    if (u.title)    prompt += '  Title idea:       ' + u.title + '\n';
    if (u.topic)    prompt += '  What it is about: ' + u.topic + '\n';
    if (u.audience) prompt += '  Target audience:  ' + u.audience + '\n';
    if (u.goal)     prompt += '  Primary goal:     ' + u.goal + '\n';
    if (u.hub_id)     prompt += '  User chose hub:     ' + u.hub_id + ' (do NOT change this)\n';
    if (u.cluster_id) prompt += '  User chose cluster: ' + u.cluster_id + ' (do NOT change this)\n';

    if (hubs.length && !u.hub_id) {
      prompt += '\nAvailable hubs (pick the best match by id, or return null if none fit — the user can assign later):\n';
      for (var hi = 0; hi < hubs.length; hi++) {
        prompt += '  - id="' + hubs[hi].id + '" name="' + hubs[hi].name + '"';
        if (hubs[hi].pillar_keyword) prompt += ' pillar="' + hubs[hi].pillar_keyword + '"';
        if (hubs[hi].description) prompt += ' ' + hubs[hi].description;
        prompt += '\n';
      }
    }
    if (clusters.length && !u.cluster_id) {
      prompt += '\nAvailable clusters (pick by id if one fits the chosen or suggested hub, else null):\n';
      for (var ci = 0; ci < clusters.length; ci++) {
        prompt += '  - id="' + clusters[ci].id + '" hub="' + clusters[ci].hub_id + '" name="' + clusters[ci].name + '"';
        if (clusters[ci].description) prompt += ' — ' + clusters[ci].description;
        prompt += '\n';
      }
    }

    if (types.length) {
      prompt += '\nAvailable content types (return one EXACT name from this list): ' + types.join(', ') + '\n';
    }

    prompt += brandSnippet('content');

    prompt += '\n\nProduce a JSON object with:\n';
    prompt += '  title:         polished, publishable headline (6-14 words)\n';
    prompt += '  content_type:  EXACT name from the list above, or "Blog Post" if unsure\n';
    prompt += '  hub_id:        id of a matching hub from the list, OR null\n';
    prompt += '  cluster_id:    id of a matching cluster from the list, OR null\n';
    prompt += '  basic_info: {\n';
    prompt += '    audience:            1-sentence description,\n';
    prompt += '    goal:                primary outcome (e.g. "drive demo signups"),\n';
    prompt += '    funnel_stage:        "awareness" | "consideration" | "decision",\n';
    prompt += '    word_count_min:      integer (e.g. 1500),\n';
    prompt += '    word_count_max:      integer (e.g. 3000),\n';
    prompt += '    search_intent:       "informational" | "commercial" | "transactional" | "navigational",\n';
    prompt += '    tone_of_voice:       short descriptor (e.g. "friendly expert")\n';
    prompt += '  },\n';
    prompt += '  keywords: {\n';
    prompt += '    primary:   { "keyword": "...", "volume": 0 },\n';
    prompt += '    secondary: ["...", "..."]   // 3-5 items,\n';
    prompt += '    lsi:       ["...", "..."]   // 3-6 items\n';
    prompt += '  },\n';
    prompt += '  research: {\n';
    prompt += '    angles:          ["angle A", "angle B", "angle C"],\n';
    prompt += '    selected_angle:  "the strongest of the three",\n';
    prompt += '    uvp:             "unique value proposition — why read this over the alternatives",\n';
    prompt += '    questions:       ["q1", "q2", "q3"]    // 3-5 questions the content must answer\n';
    prompt += '  }' + (mode === 'refresh' ? ',\n  refresh_notes: ["what to add/remove/update vs. the existing page"] // 3-6 items\n' : '\n');
    prompt += '}\n\nRespond ONLY with the JSON object. No prose.';

    callAIWithRetry(prompt, function(text) {
      var parsed = parseJSON(text);
      if (!parsed || !parsed.title) {
        if (onError) onError('empty-response');
        else toast('AI returned an empty brief', 'error');
        return;
      }
      // Normalise shape so the wizard never has to guard against missing fields.
      parsed.basic_info = parsed.basic_info || {};
      parsed.keywords = parsed.keywords || { primary: { keyword: '', volume: 0 }, secondary: [], lsi: [] };
      parsed.keywords.primary = parsed.keywords.primary || { keyword: '', volume: 0 };
      if (!Array.isArray(parsed.keywords.secondary)) parsed.keywords.secondary = [];
      if (!Array.isArray(parsed.keywords.lsi))       parsed.keywords.lsi = [];
      parsed.research = parsed.research || {};
      if (!Array.isArray(parsed.research.angles))    parsed.research.angles = [];
      if (!Array.isArray(parsed.research.questions)) parsed.research.questions = [];

      // Validate hub_id / cluster_id against the maps — AI sometimes hallucinates
      if (parsed.hub_id && !S.hubMap[parsed.hub_id])         parsed.hub_id = null;
      if (parsed.cluster_id && !S.clusterMap[parsed.cluster_id]) parsed.cluster_id = null;
      // If cluster points to a different hub than the one picked, clear it
      if (parsed.cluster_id && parsed.hub_id) {
        var cl = S.clusterMap[parsed.cluster_id];
        if (cl && cl.hub_id && cl.hub_id !== parsed.hub_id) parsed.cluster_id = null;
      }

      if (onSuccess) onSuccess(parsed);
    }, function(err) {
      if (onError) onError(err);
      else toast('AI Error: ' + err, 'error');
    }, 'ai-draft-content-brief', BrandService.getSystemPrompt('content'));
  }

  window._wcpAiDraftContentBrief = aiDraftContentBrief;
/* ===== 06-ai-actions/05-suggest-priority.js ===== */
  // ============================================================
  // AI SUGGEST SITEMAP PRIORITIES (P1 / P2 / P3)
  // ============================================================
  //
  // Sends the sitemap pages (url, title, GSC metrics if present, group) to
  // the LLM and asks it to assign P1/P2/P3 per page based on traffic /
  // revenue / link-worthiness signals. Not based on pillar/cluster
  // structure — priority is a strategic judgement.
  //
  // Preview modal: user sees proposed changes per-page + reason, can
  // Accept all / Reject all / deselect individual rows before applying.
  //
  // Batches pages into chunks of 40 so large sitemaps don't blow the
  // context window.

  var SUGGEST_PRIORITY_BATCH = 40;

  function suggestSitemapPriorities() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var sm = (S.data && S.data.sitemap) || { pages: [] };
    var pages = (sm.pages || []).filter(function(p) { return p.status !== 'removed'; });
    if (!pages.length) { toast('Import sitemap pages first', 'warning'); return; }

    // Batch to keep individual prompts small
    var batches = [];
    for (var i = 0; i < pages.length; i += SUGGEST_PRIORITY_BATCH) {
      batches.push(pages.slice(i, i + SUGGEST_PRIORITY_BATCH));
    }

    var proposals = [];
    var completed = 0;
    var errored = 0;

    var buildPrompt = function(batchIndex) {
      var batch = batches[batchIndex];
      var prompt = 'Assign a priority tier (P1 / P2 / P3) to each page below.\n\n';
      prompt += 'Priority meaning:\n';
      prompt += '  P1 = HIGH — strategically important for traffic, revenue, or attracting inbound links. Worth investing internal-link equity and (later) off-page outreach.\n';
      prompt += '  P2 = MEDIUM — supporting content that helps topical depth but isn\'t a primary revenue / traffic driver.\n';
      prompt += '  P3 = STANDARD — evergreen or informational baseline; doesn\'t need special link-building attention.\n\n';
      prompt += 'Signals to use (in order of weight):\n';
      prompt += '  1. Traffic potential (GSC clicks / impressions / position / CTR if provided)\n';
      prompt += '  2. Commercial / revenue signal implied by URL + title (product / pricing / comparison pages skew higher)\n';
      prompt += '  3. Link-worthiness (definitive guides, original research, pillars skew higher)\n';
      prompt += '  4. Topical importance (reflected in the page\'s group name)\n\n';
      prompt += 'Do NOT assume every page is P1 — most should be P3. Only the top ~15-20% deserve P1.\n\n';
      prompt += '=== PAGES (batch ' + (batchIndex + 1) + '/' + batches.length + ') ===\n';
      for (var j = 0; j < batch.length; j++) {
        var p = batch[j];
        var line = 'id=' + p.id + ' | ' + (p.title || '(no title)') + ' | ' + p.url;
        if (p.clicks || p.impressions || p.position || p.ctr) {
          line += ' | clicks=' + (p.clicks || 0) + ' imp=' + (p.impressions || 0) + ' pos=' + (p.position || 0).toFixed(1) + ' ctr=' + (p.ctr || 0).toFixed(2) + '%';
        }
        var g = p.group_id && S.sitemapGroupMap ? S.sitemapGroupMap[p.group_id] : null;
        if (g) line += ' | group=' + g.name;
        prompt += line + '\n';
      }
      prompt += brandSnippet('seo');
      prompt += '\n\nRespond ONLY as JSON:\n';
      prompt += '{"pages":[{"id":"sp_xxx","priority":1,"reason":"1-sentence rationale"}]}';
      return prompt;
    };

    // Pull custom instructions saved by the preflight on batch 0 — append to
    // every subsequent batch so the user's steering applies across all calls.
    var savedInstructions = function() {
      var pa = ((S.meta.aiPreferences || {}).perAction || {})['ai-suggest-priorities'];
      var ins = pa && pa.instructions ? pa.instructions.trim() : '';
      return ins ? '\n\n--- Additional user instructions ---\n' + ins : '';
    };

    var handleBatchResult = function(text, batchIndex) {
      var parsed = parseJSON(text) || {};
      var arr = (parsed.pages || []).filter(function(x) {
        return x && x.id && (x.priority === 1 || x.priority === 2 || x.priority === 3);
      });
      proposals = proposals.concat(arr);
      completed++;
      runBatch(batchIndex + 1);
    };
    var handleBatchError = function(err, batchIndex) {
      errored++;
      console.warn('[WCP] suggest-priorities batch ' + (batchIndex + 1) + ' failed:', err);
      runBatch(batchIndex + 1);
    };

    var runBatch = function(batchIndex) {
      if (batchIndex >= batches.length) {
        if (proposals.length === 0) {
          toast('AI returned no usable proposals' + (errored ? ' (' + errored + ' batches errored)' : ''), 'error');
          return;
        }
        _openSuggestPriorityModal(proposals);
        return;
      }
      var prompt = buildPrompt(batchIndex);
      // Subsequent batches (>0) reuse provider/model + instructions from batch 0
      if (batchIndex > 0) {
        callAIWithRetry(prompt + savedInstructions(),
          function(text) { handleBatchResult(text, batchIndex); },
          function(err)  { handleBatchError(err, batchIndex); },
          'ai-suggest-priorities', BrandService.getSystemPrompt('seo'));
        return;
      }
      // Batch 0 — run through preflight (asks once, applies for all batches)
      _wcpAIPreflight.run({
        actionId: 'ai-suggest-priorities',
        title: 'Suggest sitemap priorities',
        description: 'AI will assign P1/P2/P3 to ' + pages.length + ' page' + (pages.length !== 1 ? 's' : '') + ' across ' + batches.length + ' batch' + (batches.length !== 1 ? 'es' : '') + '. You\'ll review proposed changes before applying.',
        basePrompt: prompt,
        systemPrompt: BrandService.getSystemPrompt('seo'),
        onResult: function(text) {
          if (batches.length > 1) toast('Batch 1/' + batches.length + ' done — running rest…', 'info');
          handleBatchResult(text, batchIndex);
        },
        onError: function(err) { handleBatchError(err, batchIndex); }
      });
    };

    runBatch(0);
  }

  // Preview modal — show proposals with a checkbox per row. Accept applies
  // checked changes; cancel discards all.
  function _openSuggestPriorityModal(proposals) {
    // Filter out proposals that match the current priority (nothing to change)
    var changes = [];
    for (var i = 0; i < proposals.length; i++) {
      var pg = S.sitemapPageMap[proposals[i].id];
      if (!pg) continue;
      var current = pg.priority;
      if (current === proposals[i].priority) continue;  // already set correctly
      changes.push({ page: pg, proposed: proposals[i].priority, reason: proposals[i].reason || '', current: current });
    }
    if (!changes.length) {
      toast('AI reviewed the sitemap — no priority changes suggested', 'info', 4000);
      return;
    }

    var PR = Constants.SITEMAP_PRIORITIES;
    var html = '<div class="wcp-priopose">';
    html += '<div class="wcp-priopose-hint">' + icon('circle-info') + ' Review the AI\'s proposed priorities. Uncheck any you disagree with, then click Apply.</div>';
    html += '<div class="wcp-priopose-head">';
    html += '<label><input type="checkbox" id="wcpPrioposeAll" checked> Select all (' + changes.length + ')</label>';
    html += '</div>';
    html += '<div class="wcp-priopose-list">';
    for (var j = 0; j < changes.length; j++) {
      var ch = changes[j];
      var curCfg = (ch.current === 1 || ch.current === 2 || ch.current === 3) ? PR[String(ch.current)] : null;
      var propCfg = PR[String(ch.proposed)];
      html += '<div class="wcp-priopose-row">';
      html += '<label class="wcp-priopose-check"><input type="checkbox" class="wcp-priopose-apply" data-page-id="' + esc(ch.page.id) + '" data-priority="' + ch.proposed + '" checked><span></span></label>';
      html += '<div class="wcp-priopose-main">';
      html += '<div class="wcp-priopose-title">' + esc(ch.page.title || ch.page.url) + '</div>';
      html += '<div class="wcp-priopose-url">' + esc(ch.page.url) + '</div>';
      if (ch.reason) html += '<div class="wcp-priopose-reason">' + icon('info-circle') + ' ' + esc(ch.reason) + '</div>';
      html += '</div>';
      html += '<div class="wcp-priopose-transition">';
      if (curCfg) {
        html += '<span class="wcp-sitemap-pri-pill" style="background:' + curCfg.color + '">' + curCfg.label + '</span>';
      } else {
        html += '<span class="wcp-priopose-unset">Unset</span>';
      }
      html += '<span class="wcp-priopose-arrow">→</span>';
      html += '<span class="wcp-sitemap-pri-pill" style="background:' + propCfg.color + '">' + propCfg.label + '</span>';
      html += '</div>';
      html += '</div>';
    }
    html += '</div></div>';

    openModal('AI Priority Suggestions — ' + changes.length + ' proposed', html, {
      size: 'lg',
      saveLabel: 'Apply selected',
      onSave: function() {
        var applied = 0;
        $('.wcp-priopose-apply:checked').each(function() {
          var pid = $(this).data('page-id');
          var pri = parseInt($(this).data('priority'), 10);
          if (!pid || !(pri >= 1 && pri <= 3)) return;
          if (typeof window._wcpSetSitemapPagePriority === 'function') {
            window._wcpSetSitemapPagePriority(pid, pri);
            applied++;
          }
        });
        closeModal();
        if (applied) {
          toast('Applied ' + applied + ' priority change' + (applied !== 1 ? 's' : ''), 'success');
          if (S.currentView === 'sitemap' && window._wcpRender) window._wcpRender();
        }
      }
    });

    // "Select all" toggle
    $(document).off('change.wcp-priopose-all').on('change.wcp-priopose-all', '#wcpPrioposeAll', function() {
      $('.wcp-priopose-apply').prop('checked', this.checked);
    });
  }

  // Expose for the Part 1 event handler
  window._wcpSuggestSitemapPriorities = suggestSitemapPriorities;
/* ===== 06-ai-actions/06-hub-planning.js ===== */
  // ============================================================
  // SECTION 8.6: AI ACTIONS — HUB PLANNING (per-hub)
  // ============================================================
  //
  // Two complementary actions on hub detail view:
  //
  //   aiPlanThisHub(hubId)        — User just created a hub. AI proposes
  //                                  5-7 clusters that together give the hub
  //                                  comprehensive topical coverage. Auto-
  //                                  creates the clusters and re-renders.
  //                                  User deletes any they don't want.
  //
  //   aiGapAnalysisForHub(hubId)  — Hub has some clusters / content already.
  //                                  AI analyses what's covered and proposes
  //                                  3-6 NEW clusters to fill gaps. Auto-
  //                                  creates them and re-renders.
  //
  // Both auto-create on success (per user UX choice). Toast reports counts.
  // Persistence handled by createCluster() which calls syncToTextarea().

  function aiPlanThisHub(hubId) {
    var hub = S.hubMap[hubId]; if (!hub) return;
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }

    var existingClusters = getHubClusters(hubId);
    var existingNames = existingClusters.map(function(c) { return c.name; });

    var prompt = 'Plan a complete cluster structure for this content hub. Think like a topical-authority strategist: propose 5-7 clusters that together cover the hub comprehensively. Each cluster should anchor 3-5 future content pieces.\n\n';
    prompt += '=== HUB ===\n';
    prompt += 'Name: ' + (hub.name || '') + '\n';
    if (hub.description)     prompt += 'Description: ' + hub.description + '\n';
    if (hub.pillar_keyword)  prompt += 'Pillar keyword: ' + hub.pillar_keyword + '\n';
    if (hub.target_audience) prompt += 'Target audience: ' + hub.target_audience + '\n';
    if (hub.keywords && hub.keywords.length) prompt += 'Hub keywords: ' + hub.keywords.join(', ') + '\n';

    if (existingNames.length) {
      prompt += '\nALREADY EXISTING clusters in this hub (do NOT duplicate or rephrase): ' + existingNames.join('; ') + '\n';
    }
    prompt += brandSnippet('research');

    prompt += '\n\nFor each cluster return:\n';
    prompt += '  - name: short, publishable cluster title (2-5 words)\n';
    prompt += '  - description: 1-2 sentence overview\n';
    prompt += '  - keywords: array of 4-6 target keywords for this cluster\n';
    prompt += '  - rationale: 1 sentence on why this cluster matters for the hub\n';
    prompt += '\nRespond ONLY as JSON: {"clusters":[{"name":"...","description":"...","keywords":["..."],"rationale":"..."}]}';

    _wcpAIPreflight.run({
      actionId: 'ai-plan-this-hub',
      title: 'Plan this hub',
      description: existingNames.length
        ? 'AI will propose new clusters for "' + (hub.name || 'this hub') + '" (skipping the ' + existingNames.length + ' you already have). Each accepted cluster is auto-created — delete any you don\'t want.'
        : 'AI will propose 5-7 clusters for "' + (hub.name || 'this hub') + '". Each is auto-created — delete any you don\'t want.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var proposals = (parsed.clusters || []).filter(function(c) { return c && c.name; });
        if (!proposals.length) { toast('AI returned no cluster proposals', 'warning'); return; }

        // Dedup against existing cluster names (case-insensitive)
        var existingLc = {};
        existingNames.forEach(function(n) { existingLc[(n || '').toLowerCase()] = true; });

        snapshot('AI plan hub');
        var created = 0;
        var skipped = 0;
        for (var i = 0; i < proposals.length; i++) {
          var prop = proposals[i];
          var nm = (prop.name || '').trim();
          if (!nm) continue;
          if (existingLc[nm.toLowerCase()]) { skipped++; continue; }
          existingLc[nm.toLowerCase()] = true;
          createCluster({
            name: nm,
            hub_id: hubId,
            description: prop.description || '',
            keywords: Array.isArray(prop.keywords) ? prop.keywords.slice() : []
          });
          created++;
        }
        logActivity('ai_action', hub.id, hub.name, 'AI planned hub: created ' + created + ' cluster' + (created !== 1 ? 's' : '') + (skipped ? ' (skipped ' + skipped + ' duplicates)' : ''));
        // createCluster already does buildMaps + syncToTextarea per call.
        // One render at the end refreshes the hub detail view.
        render();
        if (created > 0) {
          toast('Created ' + created + ' cluster' + (created !== 1 ? 's' : '') + (skipped ? ' — ' + skipped + ' duplicate' + (skipped !== 1 ? 's' : '') + ' skipped' : '') + '. Delete any you don\'t want.', 'success');
        } else {
          toast('All ' + proposals.length + ' proposals were duplicates of existing clusters', 'info');
        }
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function aiGapAnalysisForHub(hubId) {
    var hub = S.hubMap[hubId]; if (!hub) return;
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }

    var existingClusters = getHubClusters(hubId);
    var existingContent  = getHubContent(hubId);

    if (!existingClusters.length && !existingContent.length) {
      toast('This hub is empty — use "Plan this Hub" instead', 'info');
      return;
    }

    var prompt = 'Analyse this content hub and identify the most important COVERAGE GAPS — sub-topics the hub should cover but currently doesn\'t. Propose 3-6 NEW clusters that would fill the most strategic gaps.\n\n';
    prompt += '=== HUB ===\n';
    prompt += 'Name: ' + (hub.name || '') + '\n';
    if (hub.description)     prompt += 'Description: ' + hub.description + '\n';
    if (hub.pillar_keyword)  prompt += 'Pillar keyword: ' + hub.pillar_keyword + '\n';
    if (hub.target_audience) prompt += 'Target audience: ' + hub.target_audience + '\n';

    if (existingClusters.length) {
      prompt += '\n=== EXISTING CLUSTERS (' + existingClusters.length + ') ===\n';
      for (var i = 0; i < existingClusters.length; i++) {
        var c = existingClusters[i];
        prompt += '  - ' + (c.name || '') + (c.description ? ' — ' + c.description : '');
        if (c.keywords && c.keywords.length) {
          var kwTxt = c.keywords.map(function(k) { return typeof k === 'string' ? k : (k.keyword || ''); }).filter(Boolean).slice(0, 5).join(', ');
          if (kwTxt) prompt += ' [kw: ' + kwTxt + ']';
        }
        prompt += '\n';
      }
    }

    if (existingContent.length) {
      prompt += '\n=== EXISTING CONTENT TITLES (sample) ===\n';
      var titles = existingContent.slice(0, 15).map(function(c) { return c.title; }).filter(Boolean);
      prompt += titles.join('; ') + '\n';
    }
    prompt += brandSnippet('research');

    prompt += '\n\nAnalyse coverage across these dimensions and return clusters that fill the biggest gaps:\n';
    prompt += '  1. Missing sub-topics that competitors / topical authorities cover\n';
    prompt += '  2. Intent gaps (e.g. lots of informational, no commercial / transactional)\n';
    prompt += '  3. Funnel stage gaps (top vs middle vs bottom of funnel)\n';
    prompt += '  4. Audience-segment gaps (different personas / use cases not addressed)\n';
    prompt += '  5. Format gaps (no comparison content, no how-to, etc.)\n\n';
    prompt += 'For each cluster return:\n';
    prompt += '  - name: short, publishable cluster title (2-5 words) — must NOT duplicate any existing cluster\n';
    prompt += '  - description: 1-2 sentence overview\n';
    prompt += '  - keywords: array of 4-6 target keywords\n';
    prompt += '  - gap_dimension: which of the 5 dimensions this cluster addresses\n';
    prompt += '  - rationale: 1 sentence explaining the gap this fills\n';
    prompt += '\nRespond ONLY as JSON: {"clusters":[{"name":"...","description":"...","keywords":["..."],"gap_dimension":"...","rationale":"..."}]}';

    _wcpAIPreflight.run({
      actionId: 'ai-gap-analysis-hub',
      title: 'Find gaps in this hub',
      description: 'AI will analyse the ' + existingClusters.length + ' cluster' + (existingClusters.length !== 1 ? 's' : '') + ' and ' + existingContent.length + ' content piece' + (existingContent.length !== 1 ? 's' : '') + ' in "' + (hub.name || 'this hub') + '" and propose missing clusters. Each accepted cluster is auto-created — delete any you don\'t want.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var proposals = (parsed.clusters || []).filter(function(c) { return c && c.name; });
        if (!proposals.length) { toast('AI returned no gap proposals', 'warning'); return; }

        // Dedup against existing cluster names
        var existingLc = {};
        existingClusters.forEach(function(c) { existingLc[(c.name || '').toLowerCase()] = true; });

        snapshot('AI hub gap analysis');
        var created = 0;
        var skipped = 0;
        for (var i = 0; i < proposals.length; i++) {
          var prop = proposals[i];
          var nm = (prop.name || '').trim();
          if (!nm) continue;
          if (existingLc[nm.toLowerCase()]) { skipped++; continue; }
          existingLc[nm.toLowerCase()] = true;
          // Stash the rationale in description so the user sees WHY the gap was flagged
          var desc = prop.description || '';
          if (prop.rationale) desc = (desc ? desc + ' ' : '') + '[Gap: ' + prop.rationale + ']';
          createCluster({
            name: nm,
            hub_id: hubId,
            description: desc,
            keywords: Array.isArray(prop.keywords) ? prop.keywords.slice() : []
          });
          created++;
        }
        logActivity('ai_action', hub.id, hub.name, 'AI gap analysis: created ' + created + ' cluster' + (created !== 1 ? 's' : '') + (skipped ? ' (skipped ' + skipped + ' duplicates)' : ''));
        render();
        if (created > 0) {
          toast('Created ' + created + ' gap-fill cluster' + (created !== 1 ? 's' : '') + (skipped ? ' — ' + skipped + ' duplicate' + (skipped !== 1 ? 's' : '') + ' skipped' : '') + '. Delete any you don\'t want.', 'success');
        } else {
          toast('All ' + proposals.length + ' proposals duplicate existing clusters — no gaps found', 'info');
        }
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  // Expose for events
  window._wcpAiPlanThisHub = aiPlanThisHub;
  window._wcpAiGapAnalysisForHub = aiGapAnalysisForHub;

