  // ── Save step data from DOM ──
/* ===== 16-setup-wizard/11-data-nav.js ===== */
  function wizardSaveStepData() {
    var sd = wizardGetSD();
    var step = wizardGetStep();

    // Read all simple fields
    $('.wcp-wizard-field').each(function() {
      var $f = $(this);
      var path = $f.data('wizard-path');
      if (!path) return;
      var val = $f.val();

      // Handle nested paths like "brandOverrides.brand_name" and "seoGoals.monthly_target"
      var parts = path.split('.');
      if (parts.length === 2) {
        sd[parts[0]] = sd[parts[0]] || {};
        if ($f.attr('type') === 'number') val = val ? parseFloat(val) : 0;
        sd[parts[0]][parts[1]] = val;
      } else if (path.indexOf('hub-name-') === 0) {
        var hi = parseInt(path.replace('hub-name-', ''), 10);
        sd.contentHubs = sd.contentHubs || [];
        if (sd.contentHubs[hi]) sd.contentHubs[hi].name = val;
      } else if (path.indexOf('hub-kw-') === 0) {
        var hki = parseInt(path.replace('hub-kw-', ''), 10);
        sd.contentHubs = sd.contentHubs || [];
        if (sd.contentHubs[hki]) sd.contentHubs[hki].pillar_keyword = val;
      } else if (path.indexOf('hub-desc-') === 0) {
        var hdi = parseInt(path.replace('hub-desc-', ''), 10);
        sd.contentHubs = sd.contentHubs || [];
        if (sd.contentHubs[hdi]) sd.contentHubs[hdi].description = val;
      } else if (path.indexOf('cluster-name-') === 0) {
        var ci = parseInt(path.replace('cluster-name-', ''), 10);
        sd.contentClusters = sd.contentClusters || [];
        if (sd.contentClusters[ci]) sd.contentClusters[ci].name = val;
      } else {
        if ($f.attr('type') === 'number') val = val ? parseFloat(val) : 0;
        sd[path] = val;
      }
    });

    // Handle primary markets as array
    if (sd.seoGoals && typeof sd.seoGoals.primary_markets === 'string') {
      sd.seoGoals.primary_markets = sd.seoGoals.primary_markets.split(',').map(function(s) { return s.trim(); }).filter(Boolean);
    }

    // AI picker selection on step 5: the inline-picker change handler in
    // src/part2b/14-events.js already calls LLMService.savePreference(...)
    // on every change, which writes S.meta.aiPreferences.appDefault.
    // No need to mirror into setupData any more — appDefault is the canonical store.

    S.meta.workspace.setupData = sd;
    syncToTextarea();
  }

  // ── Validation ──
  function wizardValidateStep(idx) {
    var sd = wizardGetSD();
    var errors = [];
    switch (idx) {
      case 0:
        if (!sd.workspaceName || !sd.workspaceName.trim()) errors.push('Workspace name is required');
        break;
      case 2:
        var hubs = sd.contentHubs || [];
        var validHubs = hubs.filter(function(h) { return h.name && h.name.trim(); });
        if (!validHubs.length) errors.push('Add at least one content hub with a name');
        break;
      case 3:
        var defaultTypes = (window._wcpGetDefaultContentTypes || function() { return []; })();
        var selIds = sd.selectedTypeIds || defaultTypes.map(function(t) { return t.id; });
        var customLen = (sd.customTypes || []).length;
        if (!selIds.length && !customLen) errors.push('Select at least one content type');
        break;
      case 4:
        if (!sd.seoGoals || !sd.seoGoals.monthly_target || sd.seoGoals.monthly_target < 1) errors.push('Monthly content target must be at least 1');
        break;
    }
    return { valid: errors.length === 0, errors: errors };
  }

  function wizardValidateAll() {
    var errors = [], warnings = [];
    var sd = wizardGetSD();

    // Required checks
    if (!sd.workspaceName || !sd.workspaceName.trim()) errors.push('Workspace name is required (Step 1)');
    var hubs = sd.contentHubs || [];
    if (!hubs.filter(function(h) { return h.name && h.name.trim(); }).length) errors.push('Add at least one content hub (Step 3)');
    var defaultTypes = (window._wcpGetDefaultContentTypes || function() { return []; })();
    var selIds = sd.selectedTypeIds || defaultTypes.map(function(t) { return t.id; });
    if (!selIds.length && !(sd.customTypes || []).length) errors.push('Select at least one content type (Step 4)');
    if (!sd.seoGoals || !sd.seoGoals.monthly_target || sd.seoGoals.monthly_target < 1) errors.push('Set a monthly content target (Step 5)');

    // Warnings
    if (!(S.brand && S.brand.configured)) {
      var bo = sd.brandOverrides || {};
      if (!bo.brand_name && !bo.industry) warnings.push('No brand data detected and no overrides set — AI features will work without brand context');
    }
    if (!LLMService.isConfigured()) warnings.push('No AI providers configured — AI features will be unavailable');
    var clustered = (sd.contentClusters || []).filter(function(c) { return c.name && c.name.trim(); });
    if (hubs.length && !clustered.length) warnings.push('No clusters added — consider adding clusters to organize content within hubs');

    return { valid: errors.length === 0, errors: errors, warnings: warnings };
  }

  // ── Navigation ──
  function wizardNextStep() {
    wizardSaveStepData();
    var step = wizardGetStep();
    var v = wizardValidateStep(step);
    if (!v.valid) {
      // Show error
      var $body = $('#wizardStepBody');
      $body.find('.wcp-wizard-error').remove();
      for (var i = 0; i < v.errors.length; i++) {
        $body.prepend('<div class="wcp-wizard-error">' + icon('circle-exclamation') + ' ' + esc(v.errors[i]) + '</div>');
      }
      return;
    }
    S.meta.workspace.setupStep = step + 1;
    syncToTextarea();
    render();
  }

  function wizardPrevStep() {
    wizardSaveStepData();
    var step = wizardGetStep();
    if (step > 0) {
      S.meta.workspace.setupStep = step - 1;
      syncToTextarea();
      render();
    }
  }

  function wizardGoToStep(stepIdx) {
    if (typeof stepIdx !== 'number' || stepIdx < 0 || stepIdx >= WIZARD_STEPS.length) return;
    var currentStep = wizardGetStep();
    if (stepIdx > currentStep) return; // Can't skip ahead
    wizardSaveStepData();
    S.meta.workspace.setupStep = stepIdx;
    syncToTextarea();
    render();
  }

  // ── Dynamic hub/cluster management ──
/* ===== 16-setup-wizard/12-items.js ===== */
  function wizardAddHub() {
    wizardSaveStepData();
    var sd = wizardGetSD();
    sd.contentHubs = sd.contentHubs || [];
    var colorIdx = sd.contentHubs.length % Constants.HUB_COLORS.length;
    sd.contentHubs.push({ name: '', description: '', pillar_keyword: '', color: Constants.HUB_COLORS[colorIdx].color });
    S.meta.workspace.setupData = sd;
    syncToTextarea();
    render();
  }

  function wizardRemoveHub(idx) {
    wizardSaveStepData();
    var sd = wizardGetSD();
    sd.contentHubs = sd.contentHubs || [];
    if (idx >= 0 && idx < sd.contentHubs.length) {
      sd.contentHubs.splice(idx, 1);
      // Remove associated clusters and re-index
      sd.contentClusters = (sd.contentClusters || []).filter(function(c) { return c.hub_index !== idx; }).map(function(c) {
        if (c.hub_index > idx) c.hub_index = c.hub_index - 1;
        return c;
      });
    }
    S.meta.workspace.setupData = sd;
    syncToTextarea();
    render();
  }

  function wizardAddCluster(hubIdx) {
    wizardSaveStepData();
    var sd = wizardGetSD();
    sd.contentClusters = sd.contentClusters || [];
    sd.contentClusters.push({ name: '', hub_index: hubIdx, keywords: [] });
    S.meta.workspace.setupData = sd;
    syncToTextarea();
    render();
  }

  function wizardRemoveCluster(clusterIdx) {
    wizardSaveStepData();
    var sd = wizardGetSD();
    sd.contentClusters = sd.contentClusters || [];
    if (clusterIdx >= 0 && clusterIdx < sd.contentClusters.length) {
      sd.contentClusters.splice(clusterIdx, 1);
    }
    S.meta.workspace.setupData = sd;
    syncToTextarea();
    render();
  }

  function wizardToggleType(typeId) {
    wizardSaveStepData();
    var sd = wizardGetSD();
    var defaultTypes = (window._wcpGetDefaultContentTypes || function() { return []; })();
    sd.selectedTypeIds = sd.selectedTypeIds || defaultTypes.map(function(t) { return t.id; });
    var pos = sd.selectedTypeIds.indexOf(typeId);
    if (pos === -1) sd.selectedTypeIds.push(typeId);
    else sd.selectedTypeIds.splice(pos, 1);
    S.meta.workspace.setupData = sd;
    syncToTextarea();
    render();
  }

  function wizardRemoveCustomType(idx) {
    wizardSaveStepData();
    var sd = wizardGetSD();
    sd.customTypes = sd.customTypes || [];
    if (idx >= 0 && idx < sd.customTypes.length) sd.customTypes.splice(idx, 1);
    S.meta.workspace.setupData = sd;
    syncToTextarea();
    render();
  }

  // ── AI Assistance Functions ──
/* ===== 16-setup-wizard/13-ai-actions.js ===== */
  function wizardAISuggestBrand() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var sd = wizardGetSD();
    wizardSaveStepData();
    var name = sd.workspaceName || sd.brandOverrides && sd.brandOverrides.brand_name || '';
    var prompt = 'Suggest brand profile details for a content planning workspace.\n';
    if (name) prompt += 'Brand/workspace name: ' + name + '\n';
    if (sd.brandOverrides && sd.brandOverrides.industry) prompt += 'Industry: ' + sd.brandOverrides.industry + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nSuggest missing brand profile fields.\nRespond ONLY as JSON: {"brand_name":"...","industry":"...","target_audience":"...","brand_voice":"...","writing_style":"...","content_pillars":"comma-separated pillars"}';
    _wcpAIPreflight.run({
      actionId: 'wizard-ai-brand',
      title: 'Suggest brand details',
      description: 'AI will fill any missing brand profile fields.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var bo = sd.brandOverrides || {};
        if (parsed.brand_name && !bo.brand_name) bo.brand_name = parsed.brand_name;
        if (parsed.industry && !bo.industry) bo.industry = parsed.industry;
        if (parsed.target_audience && !bo.target_audience) bo.target_audience = parsed.target_audience;
        if (parsed.brand_voice && !bo.brand_voice) bo.brand_voice = parsed.brand_voice;
        if (parsed.writing_style && !bo.writing_style) bo.writing_style = parsed.writing_style;
        if (parsed.content_pillars && !bo.content_pillars) bo.content_pillars = parsed.content_pillars;
        sd.brandOverrides = bo;
        S.meta.workspace.setupData = sd;
        syncToTextarea();
        render();
        toast('Brand suggestions applied — review and adjust', 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function wizardAISuggestHubs() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    wizardSaveStepData();
    var sd = wizardGetSD();
    var prompt = 'Suggest content hub topics for a website content strategy.\n';
    if (sd.brandOverrides && sd.brandOverrides.brand_name) prompt += 'Brand: ' + sd.brandOverrides.brand_name + '\n';
    if (sd.brandOverrides && sd.brandOverrides.industry) prompt += 'Industry: ' + sd.brandOverrides.industry + '\n';
    if (sd.brandOverrides && sd.brandOverrides.target_audience) prompt += 'Audience: ' + sd.brandOverrides.target_audience + '\n';
    var existingNames = (sd.contentHubs || []).map(function(h) { return h.name; }).filter(Boolean);
    if (existingNames.length) prompt += 'Existing hubs: ' + existingNames.join(', ') + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nSuggest 4-6 content hub topics with pillar keywords.\nRespond ONLY as JSON: {"hubs":[{"name":"Hub Name","description":"Brief description","pillar_keyword":"main keyword"}]}';
    _wcpAIPreflight.run({
      actionId: 'wizard-ai-hubs',
      title: 'Suggest content hubs',
      description: 'AI will propose 4-6 hub topics with pillar keywords.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var suggested = parsed.hubs || [];
        sd.contentHubs = sd.contentHubs || [];
        for (var i = 0; i < suggested.length; i++) {
          if (!suggested[i].name) continue;
          var exists = sd.contentHubs.some(function(h) { return h.name && h.name.toLowerCase() === suggested[i].name.toLowerCase(); });
          if (exists) continue;
          var colorIdx = sd.contentHubs.length % Constants.HUB_COLORS.length;
          sd.contentHubs.push({
            name: suggested[i].name,
            description: suggested[i].description || '',
            pillar_keyword: suggested[i].pillar_keyword || '',
            color: Constants.HUB_COLORS[colorIdx].color
          });
        }
        S.meta.workspace.setupData = sd;
        syncToTextarea();
        render();
        toast('Added ' + suggested.length + ' hub suggestions', 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function wizardAISuggestClusters(hubIdx) {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    wizardSaveStepData();
    var sd = wizardGetSD();
    var hub = (sd.contentHubs || [])[hubIdx];
    if (!hub || !hub.name) { toast('Name the hub first', 'warning'); return; }
    var prompt = 'Suggest content clusters (sub-topics) for this content hub.\n\nHub: ' + hub.name + '\n';
    if (hub.description) prompt += 'Description: ' + hub.description + '\n';
    if (hub.pillar_keyword) prompt += 'Pillar keyword: ' + hub.pillar_keyword + '\n';
    if (sd.brandOverrides && sd.brandOverrides.industry) prompt += 'Industry: ' + sd.brandOverrides.industry + '\n';
    prompt += brandSnippet('research');
    prompt += '\n\nSuggest 4-6 clusters.\nRespond ONLY as JSON: {"clusters":[{"name":"Cluster Name"}]}';
    _wcpAIPreflight.run({
      actionId: 'wizard-ai-clusters',
      title: 'Suggest clusters',
      description: 'AI will suggest 4-6 sub-topic clusters for hub "' + (hub.name || '') + '".',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('research'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        var suggested = parsed.clusters || [];
        sd.contentClusters = sd.contentClusters || [];
        var existing = sd.contentClusters.filter(function(c) { return c.hub_index === hubIdx; }).map(function(c) { return (c.name || '').toLowerCase(); });
        for (var i = 0; i < suggested.length; i++) {
          if (!suggested[i].name) continue;
          if (existing.indexOf(suggested[i].name.toLowerCase()) !== -1) continue;
          sd.contentClusters.push({ name: suggested[i].name, hub_index: hubIdx, keywords: [] });
        }
        S.meta.workspace.setupData = sd;
        syncToTextarea();
        render();
        toast('Added cluster suggestions for ' + hub.name, 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function wizardAISuggestTypes() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    wizardSaveStepData();
    var sd = wizardGetSD();
    var defaultTypes = (window._wcpGetDefaultContentTypes || function() { return []; })();
    var existingNames = defaultTypes.map(function(t) { return t.name; }).join(', ');
    var prompt = 'Suggest additional content types for a content planning workspace.\n';
    if (sd.brandOverrides && sd.brandOverrides.industry) prompt += 'Industry: ' + sd.brandOverrides.industry + '\n';
    prompt += 'Existing types: ' + existingNames + '\n';
    prompt += brandSnippet('content');
    prompt += '\n\nSuggest 2-3 additional content types that complement the existing ones.\nRespond ONLY as JSON: {"types":[{"name":"Type Name","description":"Brief description","icon":"font-awesome-icon-name","color":"#hex"}]}';
    _wcpAIPreflight.run({
      actionId: 'wizard-ai-types',
      title: 'Suggest content types',
      description: 'AI will propose 2-3 additional content types complementing the defaults.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('content'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        sd.customTypes = sd.customTypes || [];
        var suggested = parsed.types || [];
        for (var i = 0; i < suggested.length; i++) {
          if (!suggested[i].name) continue;
          sd.customTypes.push({
            id: generateId('ct'),
            name: suggested[i].name,
            description: suggested[i].description || '',
            icon: suggested[i].icon || 'file',
            color: suggested[i].color || '#80868b'
          });
        }
        S.meta.workspace.setupData = sd;
        syncToTextarea();
        render();
        toast('Added ' + suggested.length + ' type suggestions', 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function wizardAISuggestSEOGoals() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    wizardSaveStepData();
    var sd = wizardGetSD();
    var prompt = 'Suggest realistic 6-month SEO goals for a content strategy.\n';
    if (sd.brandOverrides && sd.brandOverrides.industry) prompt += 'Industry: ' + sd.brandOverrides.industry + '\n';
    if (sd.seoGoals && sd.seoGoals.da_current) prompt += 'Current DA: ' + sd.seoGoals.da_current + '\n';
    if (sd.seoGoals && sd.seoGoals.traffic_current) prompt += 'Current monthly traffic: ' + sd.seoGoals.traffic_current + '\n';
    var hubCount = (sd.contentHubs || []).length;
    if (hubCount) prompt += 'Planned content hubs: ' + hubCount + '\n';
    prompt += brandSnippet('seo');
    prompt += '\n\nSuggest realistic targets.\nRespond ONLY as JSON: {"monthly_target":8,"da_target":40,"traffic_target":25000,"keywords_target":50}';
    _wcpAIPreflight.run({
      actionId: 'wizard-ai-seo',
      title: 'Suggest SEO goals',
      description: 'AI will propose realistic 6-month SEO targets.',
      basePrompt: prompt,
      systemPrompt: BrandService.getSystemPrompt('seo'),
      onResult: function(text) {
        var parsed = parseJSON(text);
        sd.seoGoals = sd.seoGoals || {};
        if (parsed.monthly_target) sd.seoGoals.monthly_target = parsed.monthly_target;
        if (parsed.da_target) sd.seoGoals.da_target = parsed.da_target;
        if (parsed.traffic_target) sd.seoGoals.traffic_target = parsed.traffic_target;
        if (parsed.keywords_target) sd.seoGoals.keywords_target = parsed.keywords_target;
        S.meta.workspace.setupData = sd;
        syncToTextarea();
        render();
        toast('SEO goal suggestions applied', 'success');
      },
      onError: function(err) { toast('AI Error: ' + err, 'error'); }
    });
  }

  function wizardAITestConnection() {
    if (!LLMService.isConfigured()) { toast('No AI providers configured', 'warning'); return; }
    var $btn = $('[data-action="wizard-ai-test"]');
    $btn.prop('disabled', true).html(icon('spinner') + ' Testing...');
    var $result = $('#wizardAITestResult');
    $result.html('');
    LLMService.callAI('Respond with exactly this JSON: {"success":true,"message":"Hello from AI!"}', function(text) {
      wizardGetSD().aiTested = true;
      // Provider/model already persisted to S.meta.aiPreferences.appDefault by the
      // inline-picker change handler (src/part2b/14-events.js calls savePreference
      // on every provider/model change). No need to mirror into setupData.
      syncToTextarea();
      $result.html('<div class="wcp-wizard-ai-test-result success">' + icon('check-circle') + ' AI connection verified! Response received successfully.</div>');
      $btn.prop('disabled', false).html(icon('bolt') + ' Send Test Prompt');
      toast('AI connection successful!', 'success');
    }, function(err) {
      $result.html('<div class="wcp-wizard-ai-test-result error">' + icon('circle-exclamation') + ' Connection failed: ' + esc(err) + '</div>');
      $btn.prop('disabled', false).html(icon('bolt') + ' Send Test Prompt');
      toast('AI test failed: ' + err, 'error');
    }, 'wizard-ai-test', '');
  }

  // ── Completion ──
/* ===== 16-setup-wizard/14-complete-reset.js ===== */
  function wizardCompleteSetup() {
    wizardSaveStepData();
    var v = wizardValidateAll();
    if (!v.valid) {
      for (var i = 0; i < v.errors.length; i++) toast(v.errors[i], 'error', 5000);
      return;
    }

    var sd = wizardGetSD();

    // 1. Workspace info
    S.meta.workspace.name = sd.workspaceName || 'Content Hub';
    S.meta.workspace.description = sd.workspaceDescription || '';
    S.meta.settings.timezone = sd.timezone || S.meta.settings.timezone || 'Asia/Kolkata';

    // 2. Brand overrides
    if (sd.brandOverrides && Object.keys(sd.brandOverrides).filter(function(k) { return sd.brandOverrides[k]; }).length) {
      S.meta.brandOverrides = sd.brandOverrides;
    }

    // 3. Create hubs
    var hubIdMap = {};
    var hubsData = sd.contentHubs || [];
    for (var hi = 0; hi < hubsData.length; hi++) {
      if (!hubsData[hi].name || !hubsData[hi].name.trim()) continue;
      var newHub = createHub({
        name: hubsData[hi].name.trim(),
        description: hubsData[hi].description || '',
        color: hubsData[hi].color || Constants.HUB_COLORS[hi % Constants.HUB_COLORS.length].color,
        pillar_keyword: hubsData[hi].pillar_keyword || ''
      });
      hubIdMap[hi] = newHub.id;
    }

    // 4. Create clusters
    var clustersData = sd.contentClusters || [];
    for (var ci = 0; ci < clustersData.length; ci++) {
      if (!clustersData[ci].name || !clustersData[ci].name.trim()) continue;
      var parentHubId = hubIdMap[clustersData[ci].hub_index] || '';
      createCluster({
        name: clustersData[ci].name.trim(),
        hub_id: parentHubId,
        keywords: clustersData[ci].keywords || []
      });
    }

    // 5. Content types
    var defaultTypes = (window._wcpGetDefaultContentTypes || function() { return []; })();
    var selectedIds = sd.selectedTypeIds || defaultTypes.map(function(t) { return t.id; });
    S.data.content_types = defaultTypes.filter(function(t) { return selectedIds.indexOf(t.id) !== -1; });
    // Add custom types
    var customs = sd.customTypes || [];
    for (var cti = 0; cti < customs.length; cti++) {
      var ct = customs[cti];
      S.data.content_types.push({
        id: ct.id || generateId('ct'),
        name: ct.name, icon: ct.icon || 'file', description: ct.description || '',
        color: ct.color || '#80868b', instructions: '', default_schema: 'Article',
        snippet_targets: [], default_intent: 'informational', cw_content_type: ct.name.toLowerCase().replace(/\s+/g, '_'),
        word_count_range: { min: 1000, max: 3000 }, fields: ['title', 'meta_description']
      });
    }

    // 6. SEO goals
    if (sd.seoGoals) {
      var sg = S.meta.settings.seo_goals;
      if (sd.seoGoals.monthly_target) sg.monthly_target = sd.seoGoals.monthly_target;
      if (sd.seoGoals.da_current !== undefined) sg.da_current = sd.seoGoals.da_current;
      if (sd.seoGoals.da_target) sg.da_target = sd.seoGoals.da_target;
      if (sd.seoGoals.traffic_current !== undefined) sg.traffic_current = sd.seoGoals.traffic_current;
      if (sd.seoGoals.traffic_target) sg.traffic_target = sd.seoGoals.traffic_target;
      if (sd.seoGoals.keywords_current !== undefined) sg.keywords_current = sd.seoGoals.keywords_current;
      if (sd.seoGoals.keywords_target) sg.keywords_target = sd.seoGoals.keywords_target;
      if (sd.seoGoals.primary_markets && sd.seoGoals.primary_markets.length) sg.primary_markets = sd.seoGoals.primary_markets;
    }

    // 7. AI default — already persisted by the inline-picker change handler
    // in src/part2b/14-events.js as the user selects on step 5. Kept here as
    // a fallback for any legacy setup data carrying the old aiProvider/aiModel
    // fields (e.g. resumed from a saved wizard started before this refactor).
    if (sd.aiProvider && sd.aiModel) {
      S.meta.aiPreferences.appDefault = { provider: sd.aiProvider, model: sd.aiModel };
    }

    // 8. Finalize
    S.meta.workspace.configured = true;
    S.meta.workspace.setupCompleted = new Date().toISOString();

    var hubCount = Object.keys(hubIdMap).length;
    var clusterCount = clustersData.filter(function(c) { return c.name && c.name.trim(); }).length;
    logActivity('setup_completed', '', '', 'Setup wizard completed — ' + hubCount + ' hubs, ' + clusterCount + ' clusters created');
    if (snapshot) snapshot('Setup wizard complete');
    buildMaps(); syncToTextarea(); render();
    toast('Workspace configured! Welcome to your Content Planner.', 'success', 6000);
  }

  // ── Reset (re-enter wizard) ──
  function wizardResetSetup() {
    S.meta.workspace.configured = false;
    S.meta.workspace.setupStep = 0;
    S.meta.workspace.setupStarted = '';
    S.meta.workspace.setupCompleted = '';
    S.meta.workspace.setupData = {};
    logActivity('setup_started', '', '', 'Setup wizard restarted');
    syncToTextarea(); navigate('dashboard');
    toast('Setup wizard restarted', 'info');
  }

/* ===== 16-setup-wizard/15-events.js ===== */
  // ── Wizard event handlers ──
  function setupWizardEvents() {
    var ns = '.wcp2b-wiz';
    $(document).off('click' + ns + '-next').on('click' + ns + '-next', '[data-action="wizard-next"]', wizardNextStep);
    $(document).off('click' + ns + '-prev').on('click' + ns + '-prev', '[data-action="wizard-prev"]', wizardPrevStep);
    $(document).off('click' + ns + '-step').on('click' + ns + '-step', '[data-action="wizard-go-step"]', function() {
      var step = parseInt($(this).data('step'), 10);
      if (!isNaN(step)) wizardGoToStep(step);
    });
    $(document).off('click' + ns + '-complete').on('click' + ns + '-complete', '[data-action="wizard-complete"]', wizardCompleteSetup);
    $(document).off('click' + ns + '-reset').on('click' + ns + '-reset', '[data-action="wizard-reset"]', function() {
      openConfirmDialog({
        title: 'Re-enter Setup Wizard',
        message: 'This will reset your workspace configuration and restart the setup wizard. Your content data will not be deleted.',
        confirmLabel: 'Reset & Restart',
        danger: true,
        onConfirm: wizardResetSetup
      });
    });

    // AI buttons
    $(document).off('click' + ns + '-ai-brand').on('click' + ns + '-ai-brand', '[data-action="wizard-ai-brand"]', wizardAISuggestBrand);
    $(document).off('click' + ns + '-ai-hubs').on('click' + ns + '-ai-hubs', '[data-action="wizard-ai-hubs"]', wizardAISuggestHubs);
    $(document).off('click' + ns + '-ai-clusters').on('click' + ns + '-ai-clusters', '[data-action="wizard-ai-clusters"]', function() {
      var hubIdx = parseInt($(this).data('hub-index'), 10);
      if (!isNaN(hubIdx)) wizardAISuggestClusters(hubIdx);
    });
    $(document).off('click' + ns + '-ai-types').on('click' + ns + '-ai-types', '[data-action="wizard-ai-types"]', wizardAISuggestTypes);
    $(document).off('click' + ns + '-ai-seo').on('click' + ns + '-ai-seo', '[data-action="wizard-ai-seo"]', wizardAISuggestSEOGoals);
    $(document).off('click' + ns + '-ai-test').on('click' + ns + '-ai-test', '[data-action="wizard-ai-test"]', wizardAITestConnection);

    // Dynamic add/remove
    $(document).off('click' + ns + '-add-hub').on('click' + ns + '-add-hub', '[data-action="wizard-add-hub"]', wizardAddHub);
    $(document).off('click' + ns + '-rm-hub').on('click' + ns + '-rm-hub', '[data-action="wizard-remove-hub"]', function() {
      var idx = parseInt($(this).data('index'), 10);
      if (!isNaN(idx)) wizardRemoveHub(idx);
    });
    $(document).off('click' + ns + '-add-cl').on('click' + ns + '-add-cl', '[data-action="wizard-add-cluster"]', function() {
      var hubIdx = parseInt($(this).data('hub-index'), 10);
      if (!isNaN(hubIdx)) wizardAddCluster(hubIdx);
    });
    $(document).off('click' + ns + '-rm-cl').on('click' + ns + '-rm-cl', '[data-action="wizard-remove-cluster"]', function() {
      var clIdx = parseInt($(this).data('cluster-index'), 10);
      if (!isNaN(clIdx)) wizardRemoveCluster(clIdx);
    });
    $(document).off('click' + ns + '-toggle-type').on('click' + ns + '-toggle-type', '[data-action="wizard-toggle-type"]', function() {
      var typeId = $(this).data('type-id');
      if (typeId) wizardToggleType(typeId);
    });
    $(document).off('click' + ns + '-rm-ctype').on('click' + ns + '-rm-ctype', '[data-action="wizard-remove-custom-type"]', function() {
      var idx = parseInt($(this).data('custom-index'), 10);
      if (!isNaN(idx)) wizardRemoveCustomType(idx);
    });

    // Auto-save on field blur
    $(document).off('blur' + ns + '-field').on('blur' + ns + '-field', '.wcp-wizard-field', function() {
      wizardSaveStepData();
    });
    $(document).off('change' + ns + '-select').on('change' + ns + '-select', 'select.wcp-wizard-field', function() {
      wizardSaveStepData();
    });
  }
